  # No guessed mapping for Samolet CAM materials: raw structured detail is supplied to extraction.\n    positive=any(material_status(p) is True for p in positions)\n    title_ok=text_class(title)!=\'non_target\' and material_status({\'name\':title}) is True\n    return positive or title_ok, positions\n\n\nclass DeveloperAdapter:\n    def __init__(self,source):\n        if source not in HOSTS:raise ValueError(\'developer_unknown_source\')\n        self.source=source\n    def fetch_by_id(self,external_id,source_url=None):\n        source=self.source;url=public_url(source,external_id)\n        if source_url and source_url.rstrip(\'/\')!=url:raise ValueError(\'developer_card_identity_mismatch\')\n        from app.reports.review_dismissals import is_dismissed\n        if is_dismissed(source,str(external_id)):return None\n        if source==\'glavstroy\':\n            from app.sources.metal_it.adapter import DETAIL\n            data=api(source,\'/graphql\',dict(operationName=\'getTradeInfo\',query=DETAIL,variables={\'id\':int(external_id)})).get(\'trade\')\n        else:data=api(source,\'/api/tender/tenders/\'+str(external_id)+\'/\')\n        if not isinstance(data,dict) or str(data.get(\'id\'))!=str(external_id):raise ValueError(\'developer_response_identity_mismatch\')\n        end=current(source,data)\n        if end is None:return None\n        positive,positions=target_evidence(source,data)\n        if not positive:return None\n        if len(data.get(\'lots\') or [])!=1:raise ValueError(\'developer_multi_lot_requires_mapping\')\n        docs=references(source,data)\n        title=data.get(\'title\') if source==\'glavstroy\' else data.get(\'name\')\n        customer=(data.get(\'customer\') or data.get(\'organizer\') or {}).get(\'title\') if source==\'glavstroy\' else \'; \'.join(str(a.get(\'name\') or \'\') for a in data.get(\'authorities\') or [])\n        return SourceTender(source=source,external_id=str(external_id),title=title,source_url=url,\n            customer_name=customer,submission_deadline=end,documents=docs,\n            raw_payload={\'stage\':\'detail\',\'procurement_status\':\'Прием заявок\',\'positions\':positions,\n                \'suppress_notifications\':True,\'developer_public_card\':data})\n    def fetch_by_url(self,url):\n        safe_url(self.source,url)\n        pat=r\'/trades/(\\d+)/info/?\' if self.source==\'glavstroy\' else r\'/tenders/(\\d+)/?\'\n        m=re.fullmatch(pat,urlsplit(url).path)\n        if not m:raise ValueError(\'developer_card_path\')\n        return self.fetch_by_id(m[1],source_url=url)\n\n\ndef materialize(tender):\n    from app.core.config import settings\n    fresh=DeveloperAdapter(tender.source).fetch_by_id(tender.external_id,tender.source_url)\n    if fresh is None:raise ValueError(\'developer_no_longer_eligible\')\n    if fresh.model_dump(mode=\'json\')!=tender.model_dump(mode=\'json\'):raise ValueError(\'developer_snapshot_changed\')\n    root=Path(settings.storage_path)/\'developer_prepared\';root.mkdir(parents=True,exist_ok=True)\n    directory=Path(tempfile.mkdtemp(prefix=tender.source+\'-\'+tender.external_id+\'-\',dir=root))\n    result=[];counter=0;total=0\n    try:\n        for doc in fresh.documents:\n            data=read(tender.source,doc.url,maximum=MAX_BYTES,document=True)\n            validate_bytes(data,Path(doc.name).suffix.lower())\n            files,counter,total=unpack(data,doc,directory,counter,total);result.extend(files)\n        p=directory/\'00_Public_positions.txt\'\n        p.write_text(\'Публичная карточка закупки. Повторения с приложениями не суммировать. Идентификаторы площадки не являются номерами строк спецификации.\\n\'+json.dumps(fresh.raw_payload[\'developer_public_card\'],ensure_ascii=False,indent=2),encoding=\'utf8\')\n        result.insert(0,SourceDocument(name=p.name,download_type=\'local_file\',local_path=str(p)))\n        return result\n    except Exception:\n        shutil.rmtree(directory,ignore_errors=True);raise\n\n\ndef enqueue(source,items,*,adapter_factory=None):\n    import redis\n    from sqlalchemy import select\n    from app.core.config import settings\n    from app.db.session import SyncSessionLocal\n    from app.models.database import Tender\n    from app.reports.review_dismissals import is_dismissed\n    from app.workers.completed_analysis import has_completed_analysis\n    from app.workers.tasks_parsing import process_new_tender\n    from app.sources.pipeline_recovery import new_token,release_owned\n    from app.sources.tektorg.backlog import deadline\n    import time\n    from app.sources.candidate_priority import ordered, retry_key, explicit_material\n    client=redis.Redis.from_url(settings.redis_url);out=[];attempts=0;details=0\n    bounded = source == \'bidzaar\'\n    cursor_key=\'candidate:detail-cursor:\'+source\n    ordered_rows=ordered(items,client.get(cursor_key)) if bounded else [(item,None) for item in items]\n    until=time.monotonic()+150\n    for item,next_cursor in ordered_rows:\n        number=str(item.get(\'external_id\') or \'\');row={\'number\':number};owned=None;published=False;token=None;phase=\'eligibility\'\n        try:\n            end=deadline(item)\n            if not end or end<=now() or is_dismissed(source,number):out.append(dict(row,status=\'no_longer_eligible\'));continue\n            with SyncSessionLocal() as db:\n                t=db.execute(select(Tender).where(Tender.source==source,Tender.external_id==number)).scalar_one_or_none()\n                if t and has_completed_analysis(db,t):out.append(dict(row,status=\'cached\'));continue\n                if t and not t.is_active:out.append(dict(row,status=\'no_longer_eligible\'));continue\n                if t and str(getattr(t.processing_status,\'value\',t.processing_status)) in (\'analyzing\',\'documents_pending\'):\n                    out.append(dict(row,status=\'in_progress\'));continue\n            if attempts>=2:out.append(dict(row,status=\'batch_limit\'));continue\n            if bounded:\n                row[\'priority\']=\'explicit_material\' if explicit_material(item) else \'needs_confirmation\'\n                if client.get(retry_key(source,item)):\n                    out.append(dict(row,status=\'detail_retry_wait\'));continue\n                if details>=10:\n                    out.append(dict(row,status=\'detail_check_limit\'));continue\n                if time.monotonic()>=until:\n                    out.append(dict(row,status=\'detail_check_time_limit\'));continue\n            phase=\'lease\';token=new_token();key=\'developer:pipeline:\'+source+\':\'+number\n            if not client.set(key,token,nx=True,ex=86400):out.append(dict(row,status=\'already_queued_or_attempted\'));continue\n            owned=key;phase=\'detail\'\n            if bounded:\n                details+=1;row[\'detail_checked\']=True\n                if next_cursor is not None:client.set(cursor_key,str(next_cursor))\n            else:attempts+=1\n            adapter=(adapter_factory or DeveloperAdapter)(source)\n            card=adapter.fetch_by_id(number,item[\'source_url\'])\n            if card is None:\n                reason=getattr(adapter,\'last_skip_reason\',None)\n                out.append(dict(row,status=\'no_longer_eligible\',reason=reason if isinstance(reason,str) else None));continue\n            if card.source != source or str(card.external_id) != number:\n                raise ValueError(\'developer_resolved_identity_mismatch\')\n            phase=\'publish\';published=True\n            if bounded:attempts+=1\n            task=process_new_tender.delay(card.model_dump(mode=\'json\'))\n            out.append(dict(row,status=\'queued\',task_id=task.id))\n        except Exception as exc:\n            # Only stable adapter error codes are published; transport exception text may carry URLs.\n            reason=str(exc) if isinstance(exc,ValueError) and str(exc).startswith((\'developer_\', \'bidzaar_\')) else \'processing_unavailable\'\n            out.append(dict(row,status=\'queue_error\',phase=phase,error_type=type(exc).__name__,reason=reason))\n            if bounded and owned and not published:\n                try:client.set(retry_key(source,item),\'error\',ex=300)\n                except Exception:pass\n            if source == \'bidzaar\':\n                from app.sources.http_refusal import refusal_status\n                if refusal_status(exc) is not None:break\n        finally:\n            if owned and not published:\n                try:release_owned(client,owned,token)\n                except Exception:pass\n    return out\n\n\ndef _collect(source,previous=None):\n    if source == \'samolet\':\n        from app.sources.samolet_search import collect_filtered\n        return collect_filtered(previous or {}, api=api, clock=now(),\n                                current=current, evidence=target_evidence, public_url=public_url)\n    previous=previous or {};clock=now();items=[];errors=[];skipped={};seen=set();requests=0\n    # Keep the first page fresh and rotate two older pages; explicit partial coverage.\n    tail=previous.get(\'next_page\',2)\n    if not isinstance(tail,int) or tail<2:tail=2\n    pages=[1,tail,tail+1];done=[];next_page=tail;total=None;checked=0;listing_complete=False\n    def skip(reason):skipped[reason]=skipped.get(reason,0)+1\n    for page in pages:\n        try:\n            requests+=1\n            if source==\'glavstroy\':\n                payload=api(source,\'/graphql\',dict(operationName=\'trades\',query=SEARCH,\n                    variables={\'tradeQueryDto\':{\'fullTextString\':\'алюм\',\'request\':False},\'limit\':20,\'skip\':(page-1)*20})).get(\'trades\')\n                if not isinstance(payload,dict):raise ValueError(\'developer_listing_shape\')\n                rows=payload.get(\'items\');total=payload.get(\'total\')\n            else:\n                payload=api(source,\'/api/tender/tenders/?limit=20&page=\'+str(page));rows=payload.get(\'results\');total=payload.get(\'count\')\n            if not isinstance(rows,list) or isinstance(total,bool) or not isinstance(total,int) or total<0 or len(rows)>20:raise ValueError(\'developer_listing_shape\')\n            ids=[str(r.get(\'id\')) for r in rows]\n            if any(not x.isdigit() for x in ids) or len(set(ids))!=len(ids):raise ValueError(\'developer_listing_identity\')\n            if rows and all(x in seen for x in ids):raise ValueError(\'developer_repeated_page\')\n            if not rows and (page-1)*20<total:raise ValueError(\'developer_missing_page\')\n            done.append(page)\n            for data in rows:\n                number=str(data[\'id\'])\n                if number in seen:continue\n                seen.add(number);checked+=1\n                end=current(source,data,clock)\n                if end is None:skip(\'not_open\');continue\n                positive,_=target_evidence(source,data)\n                if not positive:\n                    # Retain uncertainty in counts; never describe this as no market opportunities.\n                    skip(\'product_unconfirmed_in_listing\');continue\n                items.append({\'source\':source,\'external_id\':number,\'title\':data.get(\'title\') or data.get(\'name\'),\n                    \'source_url\':public_url(source,number),\'submission_deadline\':end.isoformat()})\n            if page*20>=total:\n                next_page=2;listing_complete=(page==1 or tail==2);break\n            if len(rows)!=20:raise ValueError(\'developer_short_page\')\n            if page>1:next_page=page+1\n        except Exception as exc:\n            errors.append({\'phase\':\'listing\',\'error_type\':type(exc).__name__,\n                \'reason\':str(exc) if isinstance(exc,ValueError) and str(exc).startswith(\'developer_\') else \'request_failed\'})\n            break\n    return {\'source\':source,\'name\':NAMES[source],\'checked_at\':clock.isoformat(),\n        \'status\':\'partial\' if errors or not listing_complete else (\'ok\' if items else 