def unified_ui_error(section, anchor, source, detail):
    # No whole source, credentials or page data in diagnostics.
    raise SystemExit('UNIFIED_UI_CONTRACT_CHANGED: section='+section+'; anchor='+anchor+
                     '; '+detail+'; html_sha256='+hashlib.sha256(source.encode('utf8')).hexdigest()+
                     '; no project changes')

def unified_ui_span(source, name):
    """Locate one known top-level function; never modify another function's button.

    These three reviewed functions use a column-zero closing brace. Unknown
    layouts stop rather than trying to parse arbitrary JavaScript with regex.
    """
    import re
    signatures={'loadTenders':'async function loadTenders() {',
                'analyzeReview':'async function analyzeReview(row, button) {',
                'renderManual':'function renderManual(rows) {'}
    definitions=list(re.finditer(r'(?m)^[ \t]*(?:async\s+)?function\s+'+re.escape(name)+r'\s*\(',source))
    starts=list(re.finditer(r'(?m)^'+re.escape(signatures[name])+r'[ \t]*$',source))
    if len(definitions)!=1 or len(starts)!=1:
        unified_ui_error(name,'function',source,'definitions='+str(len(definitions)))
    start=starts[0].start()
    end=re.search(r'(?m)^}[ \t]*$',source[starts[0].end():])
    if end is None:unified_ui_error(name,'closing_brace',source,'missing')
    return start,starts[0].end()+end.end()

def unified_patch_ui(source):
    original=source
    def edit(name, patches):
        nonlocal source
        start,end=unified_ui_span(source,name)
        block=source[start:end]
        for label,old,new in patches:
            old_count,new_count=block.count(old),block.count(new)
            if new_count==1 and old_count==0:continue
            if old_count!=1 or new_count!=0:
                unified_ui_error(name,label,original,'old='+str(old_count)+',new='+str(new_count))
            block=block.replace(old,new,1)
        source=source[:start]+block+source[end:]
    edit('loadTenders',[('manual_rows',*UNIFIED_HTML_PATCHES[0])])
    edit('analyzeReview',[('response_status',*UNIFIED_HTML_PATCHES[4])])
    edit('renderManual',[('state_labels',*UNIFIED_HTML_PATCHES[1])])
    start,end=unified_ui_span(source,'renderManual');block=source[start:end]
    if "const button=tenderAction('Анализ','green',b=>analyzeReview(row,b),true);" in block:
        # Reject mixed layouts or a duplicate button instead of guessing ownership.
        if "const button=document.createElement('button')" in block:
            unified_ui_error('renderManual','analysis_button',original,'mixed_layouts')
        edit('renderManual',[('colored_analysis_button',UNIFIED_UI_MODERN_OLD,UNIFIED_UI_MODERN_NEW)])
    else:
        edit('renderManual',[('legacy_disabled',*UNIFIED_HTML_PATCHES[2]),
                             ('legacy_label',*UNIFIED_HTML_PATCHES[3])])
    return source

