    for value in requires(package) or []:
        r=Requirement(value)
        if r.marker and not r.marker.evaluate({'extra':'redis' if package in ('celery','kombu') else ''}):continue
        assert r.specifier.contains(version(r.name),prereleases=True), 'QUEUE_DEPENDENCY_REQUIREMENT: '+str(r)
