def platform_reverse(shadow):
    """Reverse this release in a temporary source copy only."""
    for rel,previous in PLATFORM_PREVIOUS.items():
        p=shadow/rel
        if p.is_file() and p.read_text() in (PLATFORM_MODULES[rel], *PLATFORM_KNOWN_PREVIOUS.get(rel, ())):p.write_text(previous)
    for rel,pairs in PLATFORM_EDITS.items():
        p=shadow/rel
        if not p.is_file():continue
        source=p.read_text()
        for old,new in reversed(pairs):
            if source.count(new)==1:source=source.replace(new,old,1)
        p.write_text(source)

def platform_changes(shadow):
    pending=[]
    for rel,source in PLATFORM_MODULES.items():
        p=shadow/rel;old=p.read_text() if p.is_file() else None
        if old not in (PLATFORM_PREVIOUS[rel],source):
            raise SystemExit('PLATFORM_SOURCE_CHANGED: '+rel+'; no project changes')
        if old!=source:pending.append((rel,source,None if old is None else old.encode('utf8')))
    for rel,pairs in PLATFORM_EDITS.items():
        p=shadow/rel;original=p.read_text();source=original
        for old,new in pairs:
            if source.count(new)==1 and old not in source:continue
            if source.count(old)!=1 or new in source:
                raise SystemExit('PLATFORM_DISPATCH_CHANGED: '+rel+'; no project changes')
            source=source.replace(old,new,1)
        if source!=original:pending.append((rel,source,original.encode('utf8')))
    for rel,source,_ in pending:compile(source,rel,'exec')
    return pending

