REPAIR_TESTS = '# Regressions run inside the existing isolated memory-Celery/temporary-SQLite suite.\ndef test_exact_failure_and_credentials(self):\n    from app.workers.failure_details import failure_details,task_failure,safe_error\n    message=\'EXTRACTION_POSITION_CONFLICT: field=width_mm; Authorization: Bearer credential\\npassword="secret phrase"\\ncookie: session=xyz; another=secret\'\n    cleaned=safe_error(message)\n    for secret in (\'credential\',\'secret phrase\',\'session=xyz\'):self.assertNotIn(secret,cleaned)\n    self.assertIn(\'field=width_mm\',cleaned)\n    r=failure_details(ValueError(message),task_id=\'child\')\n    self.assertEqual(r[\'code\'],\'EXTRACTION_POSITION_CONFLICT\');self.assertFalse(r[\'automatic_retry_safe\'])\n    self.assertEqual(task_failure(NS(state=\'FAILURE\',result=ValueError(\'actual failure\'))),(\'FAILURE\',\'actual failure\'))\n    class Pending:\n        state=\'PENDING\'\n        @property\n        def result(self):raise AssertionError(\'must not read pending\')\n    self.assertEqual(task_failure(Pending()),(\'PENDING\',None))\n\ndef test_legacy_placeholder_is_repaired_without_writes(self):\n    r=self.select();r.update(state=\'error\',error=\'ValueError\')\n    before=store.path().read_bytes()\n    projected=store.project(r,task_state=\'FAILURE\',task_error=\'EXTRACTION_DESIGNATION_CONFLICT: temper\')\n    self.assertIn(\'temper\',projected[\'error\']);self.assertEqual(before,store.path().read_bytes())\n    store.record_event(r[\'task_id\'],r[\'task_id\'],scoring.name,\'failed\',error=\'EXTRACTION_POSITION_CONFLICT: coating\')\n    self.assertIn(\'coating\',store.rows()[0][\'error\'])\n\ndef test_saved_bundle_full_hash_manifest(self):\n    import hashlib\n    from app.workers.saved_documents import saved_bundle\n    root=Path(settings.storage_path);tid=\'saved-tender\';folder=root/\'tenders\'/tid;folder.mkdir(parents=True)\n    docs=[]\n    for i in range(3):\n        p=folder/f\'{i}.docx\';p.write_bytes(b\'fixture\'+str(i).encode())\n        docs.append(NS(id=str(i),storage_uri=str(p),file_hash=hashlib.sha256(p.read_bytes()).hexdigest(),external_id=str(i),source_url=None))\n    t=NS(id=tid,raw_payload={\'document_quality\':{\'state\':\'needs_review\',\'documents\':[{\'document_id\':str(i)} for i in (2,0,1)]}})\n    result=saved_bundle(t,docs,root);self.assertEqual([x[\'external_id\'] for x in result],[\'2\',\'0\',\'1\'])\n    self.assertIsNone(saved_bundle(t,docs[:2],root))\n    p=Path(docs[0].storage_uri);p.write_bytes(b\'changed\');self.assertIsNone(saved_bundle(t,docs,root))\n    p.write_bytes(b\'fixture0\');t.raw_payload[\'gpb_documents\']={\'complete\':False};self.assertIsNone(saved_bundle(t,docs,root))\n\ndef test_real_child_exception_recorded(self):\n    tid=self.saved();r=self.select()\n    with Session() as db:\n        doc=db.get(Document,\'doc-a\');doc.extracted_text=\'FAIL_CHILD\';db.commit()\n    with start_worker(app,pool=\'solo\',perform_ping_check=False,shutdown_timeout=12,loglevel=\'CRITICAL\'):\n        root=worker.analyze_selected.apply_async(args=[r],task_id=r[\'task_id\'])\n        self.assertEqual(root.get(timeout=15,interval=.1)[\'status\'],\'queued_for_analysis\')\n        end=time.monotonic()+15\n        while time.monotonic()<end and store.rows()[0][\'state\']!=\'error\':time.sleep(.1)\n        row=store.rows()[0];self.assertEqual(row[\'state\'],\'error\');self.assertIn(\'field=width_mm\',row[\'error\'])\n        self.assertNotIn(\'SECRET\',row[\'error\'])\n        self.assertEqual(app.AsyncResult(row[\'current_task_id\']).state,\'FAILURE\')\n\ndef test_target_repair_does_not_retry_unknown_analysis_or_refusal(self):\n    from app.workers.selected_repair import decision,TARGETS\n    from datetime import datetime,timezone\n    t=NS(analysis_done=False,submission_deadline=datetime(2099,1,1,tzinfo=timezone.utc),processing_status=\'failed\',raw_payload={})\n    self.assertEqual(len(TARGETS),4)\n    record={\'source\':\'gpb\',\'state\':\'error\',\'stage\':\'analyze_tender\'}\n    self.assertEqual(decision(record,t,\'FAILURE\',\'ValueError\'),\'failure_detail_unavailable\')\n    self.assertEqual(decision(record,t,\'FAILURE\',\'EXTRACTION_POSITION_CONFLICT: mass\'),\'failure_needs_review\')\n    self.assertEqual(decision(record,t,\'PENDING\',\'Timeout\'),\'task_state_unconfirmed\')\n    t.raw_payload={\'analysis_failure\':{\'retryable\':False}}\n    self.assertEqual(decision(record,t,\'FAILURE\',\'refusal\'),\'nonretryable_failure\')\n    t.raw_payload={};record.update(source=\'zakupki_gov_ru\',stage=\'process_tender_documents\',state=\'blocked\')\n    self.assertEqual(decision(record,t,\'SUCCESS\',\'low confidence\'),\'resume_documents\')\n    t.analysis_done=True;self.assertEqual(decision(record,t,\'SUCCESS\',\'\'),\'already_analyzed\')\n    self.assertEqual(decision(record,t,\'SUCCESS\',\'\',dismissed=True),\'skip_dismissed\')\n\ndef test_official_b2b_fixture_no_documents_not_full_analysis(self):\n    from app.sources.b2b_manual import inspect_html,validate_url\n    info=inspect_html(\'4660174\',REPAIR_B2B_FIXTURE)\n    self.assertEqual(info[\'documents_state\'],\'not_uploaded\');self.assertFalse(info[\'pipeline_ready\']);self.assertTrue(info[\'subject_requires_review\'])\n    with self.assertRaisesRegex(ValueError,\'identity\'):inspect_html(\'9999999\',REPAIR_B2B_FIXTURE)\n    with self.assertRaisesRegex(ValueError,\'challenge\'):inspect_html(\'4660174\',\'<html>CAPTCHA</html>\')\n    for url in (\'http://www.b2b-center.ru/market/foo/tender-4660174/\', \'https://evil.invalid/market/foo/tender-4660174/\',\'https://www.b2b-center.ru/market/foo/tender-4660174/?token=abc\'):\n        with self.assertRaises(ValueError):validate_url(\'4660174\',url)\n\ndef test_exact_snapshot_not_unrelated_or_old_success(self):\n    from app.workers.selected_repair import snapshot_failure\n    import hashlib\n    root=Path(settings.storage_path)/\'extraction_snapshots\';root.mkdir(parents=True)\n    t=NS(title=\'Плита\',description=None,delivery_place=None,raw_payload={\'document_quality\':{\'documents\':[{\'document_id\':\'doc\'}]}})\n    doc=NS(id=\'doc\',filename=\'saved.txt\',extracted_text=\'all text\')\n    digest=hashlib.sha256(\'Плита\\n\\n\\n\\n### DOCUMENT: saved.txt\\nall text\'.encode()).hexdigest()\n    p=root/(digest[:16]+\'-one\');p.mkdir();f=p/\'responses.json\'\n    f.write_text(json.dumps({\'state\':\'failed\',\'input_sha256\':digest,\'error\':\'EXTRACTION_POSITION_CONFLICT: field=width_mm\'}))\n    self.assertIn(\'width_mm\',snapshot_failure(t,[doc],settings.storage_path)[\'message\'])\n    doc.extracted_text=\'changed\';self.assertIsNone(snapshot_failure(t,[doc],settings.storage_path));doc.extracted_text=\'all text\'\n    f.write_text(json.dumps({\'state\':\'completed\',\'input_sha256\':digest}));self.assertIsNone(snapshot_failure(t,[doc],settings.storage_path))\n\ndef test_saved_incomplete_documents_use_normal_document_queue(self):\n    import hashlib\n    tid=self.saved(good=False);r=self.select()\n    folder=Path(settings.storage_path)/\'tenders\'/tid;folder.mkdir(parents=True)\n    path=folder/\'positions.txt\';path.write_text(\'source unchanged\')\n    # The ORM test model deliberately stores only the fields used elsewhere;\n    # the manifest helper is covered with real paths/hashes in a separate test.\n    manifest=[{\'name\':path.name,\'download_type\':\'local_file\',\'local_path\':str(path)}]\n    with patch.object(worker,\'saved_bundle\',return_value=manifest),patch.object(documents,\'apply_async\',return_value=NS(id=\'ocr-child\')) as q,patch.object(scoring,\'apply_async\') as llm:\n        result=worker.analyze_selected.run(r)\n    self.assertTrue(result[\'saved_complete_manifest\']);self.assertEqual(q.call_args.kwargs[\'args\'],[tid,manifest]);llm.assert_not_called()\n    with Session() as db:self.assertTrue(db.get(Tender,tid).raw_payload[\'suppress_notifications\'])\n\ndef test_repair_submission_is_bounded_and_ambiguous_publish_not_repeated(self):\n    import app.workers.selected_repair as repair\n    from datetime import datetime,timezone\n    tid=self.saved();record=self.select()\n    # Only the authorized EIS identity is selected. Other three cannot be synthesized.\n    with Session() as db:\n        t=db.get(Tender,tid);t.source=\'zakupki_gov_ru\';t.external_id=\'0358100002226000241\';db.commit()\n    record=store.reserve({\'source\':\'zakupki_gov_ru\',\'external_id\':\'0358100002226000241\',\'title\':\'profile\'})[0]\n    store.finish(record[\'source\'],record[\'external_id\'],record[\'task_id\'],state=\'blocked\',stage=\'process_tender_documents\')\n    actual=NS(id=tid,raw_payload={},analysis_done=False,processing_status=\'failed\',submission_deadline=datetime(2099,1,1,tzinfo=timezone.utc))\n    class DB:\n        def __enter__(self):return self\n        def __exit__(self,*a):pass\n        def execute(self,stmt):\n            return NS(scalar_one_or_none=lambda:actual,scalars=lambda:NS(all=lambda:[]))\n    with patch.object(sys.modules[\'app.db.session\'],\'SyncSessionLocal\',DB),patch.object(app,\'AsyncResult\',return_value=NS(state=\'SUCCESS\')),patch.object(worker.analyze_selected,\'apply_async\',side_effect=TimeoutError(\'broker ack unknown\')) as q:\n        first=list(repair.run(apply=True));second=list(repair.run(apply=True))\n    self.assertEqual(q.call_count,1)\n    self.assertIn(\'publish_outcome_unknown\',[x[\'action\'] for x in first])\n    self.assertFalse(any(x[\'tasks_submitted\'] for x in second))\n    saved=next(x for x in store.rows() if x[\'source\']==\'zakupki_gov_ru\');self.assertEqual(saved[\'state\'],\'unknown\')\n\ndef test_validated_replay_is_forwarded_to_existing_scorer(self):\n    tid=self.saved();r=self.select()\n    proof={\'version\':\'fixture\',\'input_sha256\':\'exact-saved-input\'}\n    r[\'validated_replay\']=proof\n    with patch.object(scoring,\'apply_async\',return_value=NS(id=\'checked-child\')) as q:\n        answer=worker.analyze_selected.run(r)\n    self.assertEqual(answer[\'status\'],\'queued_for_analysis\')\n    self.assertEqual(q.call_args.kwargs[\'kwargs\'],{\'suppress_notifications\':True,\'validated_snapshot\':proof})\n    self.assertNotIn(\'force_reanalysis\',q.call_args.kwargs[\'kwargs\'])\n\ndef test_gpb_repair_requires_complete_replay_before_one_submission(self):\n    import app.workers.selected_repair as repair\n    from datetime import datetime,timezone\n    number=\'2107851\';record=self.select(number=number)\n    store.finish(\'gpb\',number,record[\'task_id\'],state=\'error\',stage=\'analyze_tender\')\n    error=\'EXTRACTION_POSITION_CONFLICT: thickness_mm\'\n    actual=NS(id=\'fixture\',source=\'gpb\',external_id=number,raw_payload={\'analysis_failure\':{\'message\':error}},analysis_done=False,processing_status=\'failed\',submission_deadline=datetime(2099,1,1,tzinfo=timezone.utc))\n    class DB:\n        def __enter__(self):return self\n        def __exit__(self,*a):pass\n        def execute(self,stmt):\n            return NS(scalar_one_or_none=lambda:actual,scalars=lambda:NS(all=lambda:[]))\n    proof={\'version\':\'fixture\',\'input_sha256\':\'bound\'}\n    replay=types.ModuleType(\'app.llm.validated_replay\')\n    def invalid(*a):raise ValueError(\'GPB_REPLAY_INCOMPLETE_RESPONSES\')\n    replay.validate_saved=invalid\n    with patch.dict(sys.modules,{\'app.llm.validated_replay\':replay}),patch.object(sys.modules[\'app.db.session\'],\'SyncSessionLocal\',DB),patch.object(app,\'AsyncResult\',return_value=NS(state=\'FAILURE\',result=ValueError(error))),patch.object(worker.analyze_selected,\'apply_async\',return_value=NS(id=\'new-child\')) as q:\n        before=store.path().read_bytes()\n        failed=list(repair.run(apply=True));q.assert_not_called()\n        self.assertEqual(before,store.path().read_bytes())\n        self.assertEqual(failed[0][\'replay_error\'],\'GPB_REPLAY_INCOMPLETE_RESPONSES\')\n        replay.validate_saved=lambda *a:(proof,{\'status\':\'offline_replay_validated\'})\n        preview=list(repair.run(apply=False));q.assert_not_called()\n        self.assertEqual(before,store.path().read_bytes())\n        self.assertEqual(preview[0][\'action\'],\'resume_validated_snapshot\')\n        result=list(repair.run(apply=True));again=list(repair.run(apply=True))\n        self.assertEqual(q.call_count,1)\n        self.assertEqual(q.call_args.kwargs[\'args\'][0][\'validated_replay\'],proof)\n        self.assertEqual(sum(x[\'tasks_submitted\'] for x in result),1)\n        self.assertFalse(any(x[\'tasks_submitted\'] for x in again))\n\ndef test_all_source_manual_repair_has_global_attempt_cap_and_policy_guard(self):\n    import app.workers.selected_repair as repair\n    from datetime import datetime,timezone\n    sources=(\'roseltorg\',\'metal_it\',\'bidzaar\',\'tektorg\',\'fabrikant\',\'samolet\',\'glavstroy\',\'pik\',\'akvilon\',\'level\',\'brusnika\',\'zakupki_gov_ru\')\n    actuals=[]\n    for source in sources:\n        r=self.select(source=source,number=\'selected:1\')\n        store.finish(source,\'selected:1\',r[\'task_id\'],state=\'blocked\',stage=\'process_tender_documents\',error=\'incomplete document\')\n        actuals.append(NS(id=source,source=source,external_id=\'selected:1\',raw_payload={},analysis_done=False,processing_status=\'failed\',submission_deadline=datetime(2099,1,1,tzinfo=timezone.utc)))\n    class DB:\n        def __enter__(self):return self\n        def __exit__(self,*a):pass\n        def execute(self,stmt):\n            params=stmt.compile().params\n            source=params.get(\'source_1\')\n            return NS(scalar_one_or_none=lambda:next(x for x in actuals if x.source==source),scalars=lambda:NS(all=lambda:[]))\n    with patch.object(sys.modules[\'app.db.session\'],\'SyncSessionLocal\',DB),patch.object(app,\'AsyncResult\',return_value=NS(state=\'SUCCESS\')),patch.object(worker.analyze_selected,\'apply_async\',return_value=NS(id=\'broker-id\')) as q:\n        preview=list(repair.run(all_sources=True));q.assert_not_called();self.assertEqual(len(preview),12)\n        first=list(repair.run(apply=True,all_sources=True));self.assertEqual(q.call_count,10)\n        self.assertEqual(sum(x[\'action\']==\'repair_batch_limit\' for x in first),2)\n        for row in store.rows():\n            if row.get(\'recovery_policy\'):\n                store.finish(row[\'source\'],row[\'external_id\'],row[\'task_id\'],state=\'blocked\',stage=\'process_tender_documents\')\n        second=list(repair.run(apply=True,all_sources=True))\n        self.assertEqual(sum(x[\'action\']==\'already_recovered_with_current_policy\' for x in second),10)\n        self.assertEqual(q.call_count,12)\n    # An uncertain acknowledgement also consumes the attempt budget.\n    for row in store.rows():\n        store.finish(row[\'source\'],row[\'external_id\'],row[\'task_id\'],state=\'blocked\',stage=\'process_tender_documents\',recovery_policy=None)\n    with patch.object(sys.modules[\'app.db.session\'],\'SyncSessionLocal\',DB),patch.object(app,\'AsyncResult\',return_value=NS(state=\'SUCCESS\')),patch.object(worker.analyze_selected,\'apply_async\',side_effect=TimeoutError(\'ack unknown\')) as q:\n        result=list(repair.run(apply=True,all_sources=True));self.assertEqual(q.call_count,10)\n        self.assertEqual(sum(x[\'action\']==\'publish_outcome_unknown\' for x in result),10)\n        self.assertEqual(sum(x[\'action\']==\'repair_batch_limit\' for x in result),2)\n\nfor name,fn in list(globals().items()):\n    if name.startswith(\'test_\') and callable(fn):setattr(ManualFlowTests,name,fn)\n'
