def repair_reverse(root):
    for rel,pairs in REPAIR_EDITS.items():
        p=root/rel
        if not p.is_file():continue
        s=p.read_text()
        for old,new in reversed(pairs):
            if s.count(new)==1:s=s.replace(new,old,1)
        p.write_text(s)

def repair_apply(root):
    for rel,pairs in REPAIR_EDITS.items():
        p=root/rel;s=p.read_text()
        for old,new in pairs:
            if s.count(new)==1:continue
            if s.count(old)!=1:raise SystemExit('MANUAL_REPAIR_CONTRACT_CHANGED: '+rel+'; no project changes')
            s=s.replace(old,new,1)
        p.write_text(s)

