def torgi_pipeline_reverse(root):
    for rel, old, new, count in reversed(TORGI_PIPELINE_EDITS):
        p=root/rel
        if p.is_file():
            s=p.read_text()
            if s.count(new)==count:p.write_text(s.replace(new,old))

def torgi_pipeline_apply(root):
    for rel, old, new, count in TORGI_PIPELINE_EDITS:
        p=root/rel;s=p.read_text()
        if s.count(old)!=count or new in s:
            raise SystemExit('TORGI_PIPELINE_CONTRACT_CHANGED: '+rel+'; no project changes')
        p.write_text(s.replace(old,new))

