def unified_apply(root, pending):
    for rel,content,_ in pending:
        atomic(root/rel,content.encode('utf8'))

def unified_module_compatible(rel, current, desired):
    """Recognize reviewed complete modules; formatting/comments are not versions.

    No loose substring, function-name or arbitrary-hash acceptance. Extra imports,
    decorators, statements and altered business logic still require review.
    """
    if current is None:return True
    accepted=[desired,UNIFIED_OLD_MODULES.get(rel),*UNIFIED_KNOWN_PREVIOUS.get(rel,{}).values()]
    if current in accepted:return True
    try:actual=ast.dump(ast.parse(current),include_attributes=False)
    except SyntaxError:return False
    return any(actual==ast.dump(ast.parse(source),include_attributes=False) for source in accepted if source is not None)

def unified_reverse_node(root, rel, old, new):
    p=root/rel
    if not p.is_file():return
    source=p.read_text();want=ast.parse(new).body
    tree=ast.parse(source)
    same=lambda a,b:ast.dump(a,include_attributes=False)==ast.dump(b,include_attributes=False)
    # Function replacement, preserving all unrelated declarations.
    if len(want)==1 and isinstance(want[0],ast.FunctionDef):
        nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==want[0].name]
        if len(nodes)==1 and same(nodes[0],want[0]):
            n=nodes[0];lines=source.splitlines(keepends=True);lines[n.lineno-1:n.end_lineno]=[old+'\n'];p.write_text(''.join(lines))
        return
    collect=next((n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='collect'),None)
    if not collect:return
    edits=[]
    for n in collect.body:
        if any(same(n,w) for w in want):edits.append(n)
    if len(edits)!=len(want):return
    first=min(n.lineno for n in edits)
    lines=source.splitlines(keepends=True)
    for n in sorted(edits,key=lambda x:x.lineno,reverse=True):
        replacement=''.join('    '+line+'\n' for line in old.splitlines()) if n.lineno==first else ''
        lines[n.lineno-1:n.end_lineno]=[replacement]
    p.write_text(''.join(lines))

def unified_prepare(root):
    """Resolve all changes in isolation; unknown code never gets overwritten."""
    import tempfile,shutil
    root=root.resolve()
    if not (root/'app/workers/celery_app.py').is_file():
        raise SystemExit('PROJECT_REQUIRED: run in tender-ai-platform-v6.2')
    if (root/'app').is_symlink():raise SystemExit('SOURCE_SYMLINK: app')
    dependency_pending=unified_dependency_changes(root)
    with tempfile.TemporaryDirectory(prefix='tender-unified-plan-') as temp:
        shadow=Path(temp)
        # Copy source only. Storage, environment, databases and credentials are excluded.
        for p in (root/'app').rglob('*'):
            if p.is_symlink():raise SystemExit('SOURCE_SYMLINK: '+str(p.relative_to(root)))
            if p.is_file() and p.suffix in ('.py','.html','.js','.css'):
                q=shadow/p.relative_to(root);q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q)
        v25_reverse(shadow)
        v24_reverse(shadow)
        public_progress_reverse(shadow)
        torgi_pipeline_reverse(shadow)
        sources_followup_reverse(shadow)
        comita_pipeline_reverse(shadow)
        registry_update_reverse(shadow)
        tender_resume_reverse(shadow)
        repair_reverse(shadow)
        platform_reverse(shadow)
        for branch in (LUKOIL_BRANCH,NORNICKEL_BRANCH,BRUSNIKA_BRANCH):
            unified_reverse_node(shadow,'app/marketplace_discovery/primary/collector.py','',branch)
        unified_reverse_node(shadow,'app/marketplace_discovery/primary/collector.py',RAD_ESTP_OLD_BRANCH,RAD_ESTP_NEW_BRANCH)
        for _,old,new in RAD_ESTP_FUNCTION_PATCHES:unified_reverse_node(shadow,'app/sources/multi_pipeline.py',old,new)
        p=shadow/'app/workers/celery_app.py';s=p.read_text()
        for part in (LUKOIL_SCHEDULE,NORNICKEL_SCHEDULE,BRUSNIKA_SCHEDULE,RAD_ESTP_SCHEDULE,UNIFIED_EVENTS_IMPORT):
            if part.strip() in s:s=s.replace(part.strip(),'')
        p.write_text(s.rstrip()+'\n')
        # Reverse only this exact release's narrow edits before applying predecessor guards.
        p=shadow/'app/api/manual_analysis.py'
        if p.is_file() and p.read_text()==UNIFIED_MODULES['app/api/manual_analysis.py']:
            p.write_text(UNIFIED_OLD_MODULES['app/api/manual_analysis.py'])
        p=shadow/'app/workers/tasks_ocr.py'
        if p.is_file():p.write_text(p.read_text().replace(UNIFIED_OCR_PATCH[1],UNIFIED_OCR_PATCH[0]))
        for rel,previous in UNIFIED_WORD_PREVIOUS.items():
            p=shadow/rel
            if p.is_file() and p.read_text() in (UNIFIED_MODULES[rel],*UNIFIED_KNOWN_PREVIOUS.get(rel,{}).values()):p.write_text(previous)
        unified_apply(shadow,check_files(shadow))
        for planner in (document_format_changes,corporate_monitor_changes,brusnika_monitor_changes,metal_document_changes,rad_estp_changes):
            unified_apply(shadow,planner(shadow))
        unified_apply(shadow,platform_changes(shadow))
        for rel,content in UNIFIED_MODULES.items():
            p=shadow/rel;old=p.read_text() if p.is_file() else None
            if not unified_module_compatible(rel,old,content):
                print('UNIFIED_UNRECOGNIZED_SOURCE:',rel,'SHA256:',hashlib.sha256(old.encode('utf8')).hexdigest(),flush=True)
                raise SystemExit('UNIFIED_VERSION_MISMATCH: '+rel+'; no project changes')
            p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
        p=shadow/'app/static/index.html'
        p.write_text(unified_patch_ui(p.read_text()))
        p=shadow/'app/workers/tasks_ocr.py';s=p.read_text();old,new=UNIFIED_OCR_PATCH
        if s.count(old)!=1:raise SystemExit('UNIFIED_OCR_CONTRACT_CHANGED; no project changes')
        p.write_text(s.replace(old,new,1))
        repair_apply(shadow)
        tender_resume_apply(shadow)
        registry_update_apply(shadow)
        comita_pipeline_apply(shadow)
        sources_followup_apply(shadow)
        torgi_pipeline_apply(shadow)
        public_progress_apply(shadow)
        v24_apply(shadow)
        v25_apply(shadow)
        p=shadow/'app/workers/celery_app.py';p.write_text(p.read_text().rstrip()+'\n'+UNIFIED_EVENTS_IMPORT)
        pending=list(dependency_pending)
        for p in sorted((shadow/'app').rglob('*')):
            if not p.is_file():continue
            rel=p.relative_to(shadow).as_posix();raw=(root/rel).read_bytes() if (root/rel).is_file() else None
            data=p.read_bytes()
            if p.suffix=='.py':compile(data,rel,'exec')
            if data!=raw:pending.append((rel,data.decode('utf8'),raw))
        return pending

