def unified_verification_script():
    # Exactly the same program runs before service shutdown and after activation.
    return '\n'.join((UNIFIED_DEPENDENCY_VERIFY,UNIFIED_VERIFY,UNIFIED_UI_VERIFY,
                      PLATFORM_VERIFY,REPAIR_VERIFY,OPEN_SOURCES_VERIFY,SOURCE_BUNDLE_VERIFY,TORGI_PIPELINE_VERIFY,PUBLIC_PROGRESS_VERIFY,PUBLIC_EXPANSION_VERIFY,V24_VERIFY))

def unified_install(root,dry_run=False):
    unified_verification_version_checks()
    import fcntl
    # A non-blocking project lock prevents overlapping builds/deployments.
    root=root.resolve()
    if not (root/'app').is_dir():raise SystemExit('PROJECT_REQUIRED')
    if dry_run:
        pending=unified_prepare(root)
        print(json.dumps({'version':UNIFIED_VERSION,'mode':'plan','files':[x[0] for x in pending],
                          'business_tasks_submitted':False,'live_connections_verified':False},ensure_ascii=False,indent=2))
        return
    lock_path=root/'.tender-unified-install.lock'
    with lock_path.open('a') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise SystemExit('INSTALL_ALREADY_RUNNING')
        _unified_deploy(root)

def _unified_deploy(root):
    import time
    services=('app','celery_worker','celery_discovery','celery_beat')
    journal=root/'backups/unified-service-state.json'
    pending=unified_prepare(root)
    running=set(run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=30).stdout.split())
    prior=None
    if journal.is_file():
        prior=json.loads(journal.read_text())
        if prior.get('version')!=UNIFIED_VERSION or not set(prior.get('running',[]))<=set(services):
            raise SystemExit('UNIFIED_DEPLOYMENT_JOURNAL_MISMATCH')
        running.update(prior['running'])
    if 'app' not in running:raise SystemExit('APP_NOT_RUNNING: no source changes or services started')
    observed=set(run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=30).stdout.split())
    backup=root/'backups'/('unified-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    old_images=prior.get('images',[]) if prior else []
    config=json.loads(run(['docker','compose','config','--format','json'],capture_output=True,text=True,timeout=30).stdout)
    build_tags=unified_build_tags(config,services)
    if not prior:
        for service in services:
            ids=run(['docker','compose','ps','-a','-q',service],capture_output=True,text=True,timeout=20).stdout.split()
            if service in observed and not ids:raise SystemExit('CONTAINER_INSPECTION_INCOMPLETE: '+service)
            if ids:
                data=json.loads(run(['docker','inspect',ids[0]],capture_output=True,text=True,timeout=20).stdout)[0]
                for mount in data.get('Mounts',[]):
                    dest=mount.get('Destination','').rstrip('/')
                    if mount.get('Type')=='bind' and (dest in ('','/app','/app/app') or dest.startswith('/app/app/')):
                        raise SystemExit('LIVE_SOURCE_BIND_MOUNT: '+service+'; source changes require a separate deployment strategy; no files changed')
        # Save the actual pre-build tag state. Container .Image can be unavailable
        # even while its container runs; it is not a reliable rollback reference.
        old_images=unified_preserve_images(build_tags,datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S%f'))
    else:
        for item in old_images:
            if item['existed'] and unified_image_id(item['backup_tag'])!=item['image_id']:
                raise SystemExit('IMAGE_BACKUP_MISSING: previous deployment cannot be safely resumed')
    for rel,_,old in pending:
        actual=(root/rel).read_bytes() if (root/rel).is_file() else None
        if actual!=old:raise SystemExit('SOURCE_CHANGED_DURING_PLAN: '+rel+'; no files changed')
    for rel,content,old in pending:
        if old is not None:atomic(backup/rel,old)
    if pending:
        atomic(backup/'manifest.json',json.dumps({'version':UNIFIED_VERSION,'files':[{'path':r,'new_file':o is None} for r,_,o in pending]},indent=2).encode())
    atomic(backup/'images.json',json.dumps(old_images,indent=2).encode())
    def restore_source():
        for rel,_,old in pending:
            if old is None:(root/rel).unlink(missing_ok=True)
            else:atomic(root/rel,old)
    try:
        unified_apply(root,pending)
        print('UNIFIED_BACKUP:',backup if pending else 'no source changes',flush=True)
        run(['docker','compose','build',*services])
        # Each suite uses an isolated process: test doubles cannot leak into later suites.
        suites=(('manual workflow',unified_test_script()),('existing pipeline',UNIFIED_BASE_TESTS),
                ('document formats',DOCUMENT_TESTS),('Word visual pages','REQUIRE_OFFICE=True\n'+UNIFIED_WORD_TESTS),('public developers',PUBLIC_DEVELOPER_TESTS),
                ('corporate monitors',LUKOIL_TESTS),('Brusnika',BRUSNIKA_TESTS),
                ('public platform integration','PLATFORM_FIXTURES = '+repr(PLATFORM_FIXTURES)+'\n'+PLATFORM_TESTS),
                ('attachment limit',METAL_LIMIT_TESTS),('RAD/ESTP',RAD_ESTP_TESTS),
                ('GPB identities and exact replay',IDENTITY_TESTS),
                ('all-source reconciliation and public monitors',ALL_SOURCES_TESTS),
                ('NAUMEN full bundles and complete reference audit',V24_TESTS),
                ('MIR Spetstender RUSAL and audit diagnostics',V25_TESTS))
        unified_run_image_tests(config,services,suites)
    except BaseException:
        restore_source()
        unified_restore_images(old_images)
        print('UNIFIED_PRECHECK_FAILED: sources restored; no service restart or business task submission',flush=True)
        raise
    # Write state before SIGTERM; a repeat invocation safely resumes a slow warm stop.
    atomic(journal,json.dumps({'version':UNIFIED_VERSION,'running':sorted(running&set(services)),
                              'images':old_images,'backup':prior.get('backup') if prior and not pending else str(backup)}).encode())
    stop=[s for s in ('celery_beat','celery_discovery','celery_worker') if s in observed]
    ids=[]
    for s in stop:ids+=run(['docker','compose','ps','-q',s],capture_output=True,text=True,timeout=20).stdout.split()
    if stop:
        print('Waiting for warm shutdown; existing tasks may finish. No force kill.',flush=True)
        run(['docker','compose','kill','--signal','SIGTERM',*stop],timeout=30)
        until=time.monotonic()+300
        while ids:
            states=run(['docker','inspect','--format','{{.State.Running}}',*ids],capture_output=True,text=True,timeout=20).stdout.split()
            if len(states)==len(ids) and all(s=='false' for s in states):break
            if time.monotonic()>until:raise SystemExit('WARM_SHUTDOWN_PENDING: rerun this same command after current tasks finish; no force kill was used')
            time.sleep(3)
    # Keep Beat stopped until the app and formerly running workers pass import checks.
    restart=[s for s in ('app','celery_worker','celery_discovery') if s in running]
    try:
        run(['docker','compose','up','-d','--no-deps',*restart],timeout=120)
        for service in restart:
            run(['docker','compose','exec','-T',service,'python','-'],input=unified_verification_script(),text=True,timeout=90)
        if 'celery_beat' in running:run(['docker','compose','up','-d','--no-deps','celery_beat'],timeout=90)
    except BaseException:
        # Do not kill newly started workers: they may already have existing tasks.
        print('UNIFIED_ACTIVATION_INCOMPLETE: Beat not intentionally resumed before checks; deployment journal retained. Rerun this command. Do not purge queues.',flush=True)
        raise
    journal.unlink(missing_ok=True)
    print('UNIFIED_INSTALLED:',UNIFIED_VERSION,flush=True)
    print('Manual pipeline uses existing queues; document and connection patches consolidated. No immediate collection, reanalysis, business DB edits or notifications by installer.',flush=True)
    print('STOPPED_SERVICES_RETAINED:',','.join(s for s in services if s not in running) or 'none',flush=True)
    for label,action in (('connections',lambda:unified_runtime('connections')),
                         ('manual',lambda:unified_runtime('manual')),('documents',lambda:unified_runtime('documents')),('queues',audit_queues)):
        try:action()
        except (OSError,subprocess.SubprocessError,SystemExit) as exc:
            print('POST_INSTALL_AUDIT_INCOMPLETE:',label,type(exc).__name__,
                  '; installation completed, queue emptiness is not confirmed',flush=True)
UNIFIED_GUIDE = 'Обновление 17.11.2026 — unified-20261117-16\n\nИсправлена проверка установки КОМИТА: прежний общий тест передавал новому\nJSON-сборщику шаблон обычной HTML-площадки, из-за чего установка откатывалась.\nПроверяются оба реальных маршрута поиска на тестовых данных и сохранение\nблокировки при неправильном ответе. Проверки приложения не отключены.\nЭто исправление установочного теста; код приложения, правила отбора, расписания\nи версия журнала unified-20261117-16 не меняются. Повторите --install-unified\nс исправленным файлом. Предыдущий UNIFIED_PRECHECK_FAILED вернул исходные файлы\nи образы, не перезапуская сервисы. Бизнес-задачи установкой не добавляются.\n\nКОМИТА / закупки РЖД: новый анонимный монитор публичных секций 223-ФЗ и коммерческих закупок.\nИспользуется подтверждённый запрос сайта, без ключа API, личного кабинета и платной подписки.\nПоиск: «алюминиевый» и вращающийся ключ существующего ассортимента, включая «алюминий» и «металлопрокат».\nДо 14 запросов за проход; первая страница и две страницы продолжения по ключу/секции.\nОдно расписание primary-comita-4h: 22 */4, часовой пояс Celery (на вашем сервере Europe/Moscow).\nКандидаты сохраняются в отчёте comita.json; до проверки полного комплекта документов они не являются «подходящими» и не передаются в LLM.\nПроверка 17.11: публичный поиск отвечает, найденные в проверенных выборках закупки архивные.\nНаличие актуальной подходящей заявки и полный путь до анализа пока не подтверждены.\n\nТорги223 и ЭТП Заказ: к существующим сборщикам добавлено чтение максимум двух карточек кандидатов за проход.\nПроверяются номер, название и все опубликованные ссылки на документы. Для Торги223 читается точный срок с MSK.\nУ ЭТП Заказ время в карточке не содержит часового пояса: UTC/МСК не назначаются произвольно.\nПоддержаны номера Торги223 с префиксом, например QR-35242. Существующие курсоры и расписания сохраняются.\nАвтоматический анализ этих источников пока не активируется: ссылка на файл не равна скачанному полному комплекту.\nПри исследовании известной карточки Торги223 вложение вернуло HTTP 503. Ошибка не скрывается и не считается успешной загрузкой.\n\n--install-unified: совместимая установка с проверками; без немедленного сбора, OCR, LLM и массовых повторов.\n--check-comita: проверка живого публичного поиска без сохранения отчёта или бизнес-данных.\n--check-public-registries: поиск Торги223 и ЭТП Заказ и чтение до двух карточек кандидатов; без документов и задач.\n--check-registry-details: две известные технические карточки, до одного вложения каждой в памяти.\nПоследний режим проверяет доступность/формат; примеры архивные или нецелевые, к участию не допускаются.\n--status и --connection-status: последние отчёты и конфигурация; наличие расписания не доказывает полный путь до анализа.\n\nОстаются незавершёнными доступ и/или документы: Tender.Pro, Сбербанк-АСТ, РТС, закрытые корпоративные секции и часть остальных публичных мониторов.\nАСТ ГОЗ и ЭТП РФ остаются отключены. Платные сервисы не добавлены. КОМИТА не дублируется новой моделью закупки.\nПравила 500 кг по одной позиции либо 200 шт. при неизвестной массе, ручные исключения и проверки качества документов сохранены.\nПолнота Word/OCR и отказы LLM не обходятся. Установка не означает повторную обработку ранее заблокированных карточек.\n\n' + UNIFIED_GUIDE

SOURCE_AUDIT_CODE = '"""Read-only source review. Public access never means a verified pipeline."""\nimport ast\nimport concurrent.futures\nimport hashlib\nimport html\nimport ipaddress\nimport json\nimport re\nimport socket\nimport ssl\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom html.parser import HTMLParser\nfrom pathlib import Path\n\nAUDIT_VERSION = \'source-review-20261119-3\'\nMAX_BYTES = 2_000_000\nVERDICT_LABELS = {\n    \'disabled_by_owner\':\'Отключено по решению пользователя\',\n    \'runtime_unknown\':\'Состояние сервера не получено\',\n    \'attention_required\':\'Есть ошибка или ограничение доступа\',\n    \'last_run_unknown\':\'Время последнего сбора не подтверждено\',\n    \'stale_report\':\'Отчёт устарел — проверить расписание и воркеры\',\n    \'partial_coverage\':\'Неполное покрытие или ошибки сбора\',\n    \'no_schedule_observed\':\'Расписание не найдено\',\n    \'monitor_only\':\'Работает монитор кандидатов; полный путь не подтверждён\',\n    \'public_listing_unavailable\':\'Сайт отвечает, но публичный реестр закупок не получен\',\n    \'adapter_required\':\'Для этого источника требуется обработчик закупок\',\n    \'public_data_needs_review\':\'Получены сведения, но целевые позиции или документы не подтверждены\',\n    \'recent_collection_and_past_analyses\':\'Есть свежий сбор и ранее завершённые анализы\',\n    \'recent_collection_analysis_unconfirmed\':\'Есть свежий сбор; завершённый анализ не подтверждён\',\n    \'not_checked_on_server\':\'Требуется запуск проверки на сервере\',\n}\nCOATING_PROPOSED = (\n    \'полимерная покраска алюминия\', \'полимерная окраска алюминия\',\n    \'полимерная покраска оцинкованной стали\', \'полимерная окраска оцинкованной стали\',\n    \'нанесение полимерного покрытия на алюминий\',\n    \'нанесение полимерного покрытия на оцинкованную сталь\',\n    \'окраска алюминиевого рулона\', \'окраска оцинкованного рулона\',\n)\n\ndef stamp():\n    return datetime.now(timezone.utc).isoformat()\n\ndef safe(value):\n    s = str(value)\n    s = re.sub(r\'https?://[^\\s<>\\"\\\']+\', \'[URL]\', s)\n    s = re.sub(r\'(?i)(authorization|cookie|token|password|secret)\\s*[:=]\\s*\\S+\', r\'\\1=[hidden]\', s)\n    return s[:600]\n\ndef age_hours(value, now):\n    try:\n        parsed = datetime.fromisoformat(str(value).replace(\'Z\', \'+00:00\'))\n        if parsed.tzinfo is None: return None\n        delta = (now - parsed).total_seconds() / 3600\n        return round(delta, 3) if delta >= 0 else None\n    except (TypeError, ValueError): return None\n\ndef summarize_report(data, now):\n    if not isinstance(data, dict): return {\'status\': \'invalid_report\'}\n    rows = data.get(\'pipeline\') or []\n    errors = data.get(\'errors\') or []\n    if not isinstance(rows,list) or not isinstance(errors,list): return {\'status\':\'invalid_report\'}\n    return {\n        \'checked_at\': data.get(\'checked_at\'),\n        \'age_hours\': age_hours(data.get(\'checked_at\'), now),\n        \'status\': data.get(\'status\'), \'pipeline_status\': data.get(\'pipeline_status\'),\n        \'coverage\': data.get(\'coverage\'), \'backlog_pending\': data.get(\'backlog_pending\'),\n        \'candidate_count\': data.get(\'candidate_count\'),\n        \'pipeline_outcomes\': dict(Counter(str(r.get(\'status\')) for r in rows if isinstance(r, dict))),\n        \'errors\': [{k: safe(e.get(k, \'\')) for k in (\'reason\',\'error_type\',\'phase\')} if isinstance(e, dict)\n                   else {\'reason\': safe(e)} for e in errors[:8]],\n        \'error_count\': len(errors),\n    }\n\ndef connection_verdict(row):\n    """Do not infer e2e completion from schedule, a queue ID or HTTP 200."""\n    if row.get(\'disabled_by_owner\'): return \'disabled_by_owner\'\n    if row.get(\'runtime_error\'): return \'runtime_unknown\'\n    report = row.get(\'report\') or {}\n    last = row.get(\'last_run\') or {}\n    current = report if report.get(\'checked_at\') else last\n    state = str(current.get(\'status\') or \'\')\n    if report.get(\'status\') in (\'invalid_report\',\'unreadable_report\'): return \'attention_required\'\n    if state in (\'public_listing_not_exposed\',\'no_public_listing_exposed\'): return \'public_listing_unavailable\'\n    if state==\'requires_adapter\': return \'adapter_required\'\n    if re.search(r\'blocked|captcha|access|timeout|failed|incomplete|unavailable\', state): return \'attention_required\'\n    age = current.get(\'age_hours\')\n    if age is None: return \'last_run_unknown\'\n    if age > (30 if row.get(\'source\') == \'zakupki_gov_ru\' else 6): return \'stale_report\'\n    if current.get(\'error_count\', 0) or state == \'partial\': return \'partial_coverage\'\n    if not row.get(\'schedule\'): return \'no_schedule_observed\'\n    if state==\'public_data_requires_review\': return \'public_data_needs_review\'\n    if \'pipeline\' not in str(row.get(\'capability\')): return \'monitor_only\'\n    if (row.get(\'analysis_done_count\') or 0) > 0: return \'recent_collection_and_past_analyses\'\n    return \'recent_collection_analysis_unconfirmed\'\n\ndef literal_keywords(root):\n    specs = (\'app/scoring/selection_policy.py\',\n             \'app/marketplace_discovery/primary/gpb_search.py\',\n             \'app/marketplace_discovery/primary/collector.py\',\n             \'app/sources/open_sources.py\', \'app/sources/bidzaar.py\',\n             \'app/sources/tender_pro/public_probe.py\')\n    out = []\n    for rel in specs:\n        p = root / rel\n        if not p.is_file(): continue\n        try: tree = ast.parse(p.read_text(encoding=\'utf-8\'))\n        except (OSError, SyntaxError, UnicodeError): continue\n        for node in ast.walk(tree):\n            if not isinstance(node, ast.Assign): continue\n            for target in node.targets:\n                if not isinstance(target, ast.Name) or target.id not in (\'FALLBACK_QUERIES\',\'QUERIES\',\'SEARCH_TERMS\',\'KEYWORDS\'): continue\n                try: values = ast.literal_eval(node.value)\n                except (ValueError, TypeError): continue\n                if isinstance(values, (tuple, list)) and all(isinstance(x, str) for x in values):\n                    out.append({\'file\': rel, \'constant\': target.id, \'values\': list(values)})\n    return {\'literal_query_lists\': out, \'scope\': \'known source files; not database search sets\',\n            \'coating_queries_proposed_not_installed\': list(COATING_PROPOSED),\n            \'coating_end_to_end_enabled\': \'not_verified\',\n            \'note\': \'Наличие слов в файле не доказывает запуск поиска или прохождение фильтра услуг.\'}\n\ndef runtime_inventory(catalog):\n    now = datetime.now(timezone.utc)\n    out = {\'checked_at\': now.isoformat(), \'sources\': [], \'errors\': []}\n    try:\n        from app.workers.celery_app import celery_app\n        from app.core.config import settings\n        from app.sources.run_status import list_runs\n        schedules = celery_app.conf.beat_schedule\n        report_root = Path(settings.storage_path) / \'marketplace_primary\'\n        runs = {r.get(\'source\'): r for r in list_runs() if isinstance(r, dict)}\n        out[\'timezone\'] = str(celery_app.conf.timezone)\n    except Exception as exc:\n        out[\'errors\'].append({\'phase\': \'runtime\', \'error_type\': type(exc).__name__})\n        return out\n    counts = {}\n    try:\n        from sqlalchemy import select, func, text\n        from app.db.session import SyncSessionLocal\n        from app.models.database import Tender\n        with SyncSessionLocal() as db:\n            db.execute(text(\'SET TRANSACTION READ ONLY\'))\n            db.execute(text("SET LOCAL statement_timeout = \'15000\'"))\n            rows = db.execute(select(Tender.source, Tender.analysis_done, func.count()).group_by(Tender.source, Tender.analysis_done)).all()\n            for source, done, count in rows:\n                if done: counts[str(source)] = count\n            db.rollback()\n        out[\'db_read\'] = \'read_only_completed\'\n    except Exception as exc:\n        out[\'db_read\'] = \'unavailable\'\n        out[\'errors\'].append({\'phase\': \'database\', \'error_type\': type(exc).__name__})\n    for item in catalog:\n        source = item[\'source\']\n        row = dict(item)\n        row[\'schedule\'] = [{\'entry\': key, \'schedule\': str(v.get(\'schedule\')), \'task\': str(v.get(\'task\'))}\n            for key,v in schedules.items() if source in tuple(v.get(\'args\') or ()) or\n            (source == \'b2b_center\' and str(v.get(\'task\',\'\')).endswith(\'.run_connected_marketplaces\'))]\n        module = row.get(\'module\')\n        path = Path(\'/app\') / Path(*module.split(\'.\')).with_suffix(\'.py\') if module else None\n        row[\'module_present\'] = bool(path and path.is_file())\n        row[\'analysis_done_count\'] = counts.get(source,0) if out[\'db_read\'] == \'read_only_completed\' else None\n        row[\'analysis_count_scope\'] = \'all_time; not suitable-card count or current-run proof\'\n        p = report_root / ((\'tender_pro_public\' if source == \'tender_pro\' else source) + \'.json\')\n        if p.is_file():\n            try:\n                if p.stat().st_size > 10_000_000: raise ValueError(\'report_size\')\n                row[\'report\'] = summarize_report(json.loads(p.read_text(encoding=\'utf-8\')), now)\n            except (OSError, ValueError, TypeError, UnicodeError): row[\'report\'] = {\'status\': \'unreadable_report\'}\n        else: row[\'report\'] = {\'status\': \'primary_report_missing\'}\n        last = runs.get(\'primary_\' + source) or runs.get(source) or {}\n        row[\'last_run\'] = {k: last.get(k) for k in (\'recorded_at\',\'status\',\'error_count\',\'queued_count\',\'found_count\')}\n        row[\'last_run\'][\'age_hours\'] = age_hours(last.get(\'recorded_at\'), now)\n        row[\'verdict\'] = connection_verdict(row)\n        row[\'verdict_description\'] = VERDICT_LABELS[row[\'verdict\']]\n        row[\'live_end_to_end_verified_by_this_audit\'] = False\n        out[\'sources\'].append(row)\n    out[\'keywords\'] = literal_keywords(Path(\'/app\'))\n    out[\'note\'] = \'Снимок конфигурации, сохранённых отчётов и БД. Новые бизнес-задачи не запускались.\'\n    return out\n\nclass PublicHTML(HTMLParser):\n    def __init__(self):\n        super().__init__(convert_charrefs=True)\n        self.ignore=0; self.words=[]; self.links=[]; self.anchor=None; self.password=False\n        self.hidden_stack=[]; self.gwt_panel=False; self.gwt_script=False; self.hidden_password=False\n    def handle_starttag(self, tag, attrs):\n        a=dict(attrs)\n        parent_hidden=any(v for _,v in self.hidden_stack)\n        hidden=(parent_hidden or \'hidden\' in a or a.get(\'aria-hidden\')==\'true\' or\n                bool(re.search(r\'(?:display\\s*:\\s*none|visibility\\s*:\\s*hidden)\',a.get(\'style\',\'\'),re.I)) or\n                bool(set(a.get(\'class\',\'\').split()) & {\'spf-hidden\',\'hidden\',\'d-none\'}))\n        if tag not in (\'area\',\'base\',\'br\',\'col\',\'embed\',\'hr\',\'img\',\'input\',\'link\',\'meta\',\'param\',\'source\',\'track\',\'wbr\'):\n            self.hidden_stack.append((tag,hidden))\n        if a.get(\'id\')==\'gwtSearchPanel\': self.gwt_panel=True\n        if tag==\'script\' and a.get(\'src\')==\'/etp/guigwt.default/guigwt.default.nocache.js\': self.gwt_script=True\n        if tag in (\'script\',\'style\'): self.ignore+=1\n        if tag==\'input\' and a.get(\'type\',\'\').lower()==\'password\':\n            if hidden:self.hidden_password=True\n            else:self.password=True\n        if tag==\'a\': self.anchor=[a.get(\'href\',\'\'),[]]\n    def handle_endtag(self, tag):\n        if tag in (\'script\',\'style\'): self.ignore=max(0,self.ignore-1)\n        if tag==\'a\' and self.anchor:\n            self.links.append((self.anchor[0], \' \'.join(self.anchor[1]))); self.anchor=None\n        for i in range(len(self.hidden_stack)-1,-1,-1):\n            if self.hidden_stack[i][0]==tag:\n                del self.hidden_stack[i:];break\n    def handle_data(self, data):\n        if not self.ignore and not any(v for _,v in self.hidden_stack):\n            self.words.append(data)\n            if self.anchor: self.anchor[1].append(data)\n\ndef approved_url(url, hosts):\n    try:\n        p=urllib.parse.urlsplit(url)\n        return (p.scheme==\'https\' and p.hostname in hosts and not p.username and not p.password and\n                p.port in (None,443) and not p.fragment and not p.query and\n                not re.search(r\'/(login|logout|auth|registration|register|captcha)(/|$)\',p.path,re.I))\n    except ValueError: return False\n\ndef public_dns(host):\n    addresses={x[4][0] for x in socket.getaddrinfo(host,443,type=socket.SOCK_STREAM)}\n    if not addresses or any(not ipaddress.ip_address(x).is_global for x in addresses):\n        raise ValueError(\'non_public_address\')\n\nclass NoRedirect(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl): return None\n\nclass SourceAccessError(ValueError):\n    def __init__(self, reason, **evidence):\n        super().__init__(reason)\n        self.evidence=evidence\n\ndef redirect_origin(url):\n    """Record a destination for review without query, path, fragment or credentials."""\n    try:\n        p=urllib.parse.urlsplit(url)\n        if p.scheme not in (\'http\',\'https\') or not p.hostname: return \'not_http_origin\'\n        return p.scheme+\'://\'+p.hostname\n    except ValueError: return \'invalid_origin\'\n\ndef network_failure(exc):\n    reason=exc.reason if isinstance(exc,urllib.error.URLError) else exc\n    if isinstance(reason,ssl.SSLCertVerificationError):\n        return {\'status\':\'tls_verification_failed\',\'failed_phase\':\'tls\',\n                \'verify_code\':getattr(reason,\'verify_code\',None),\n                \'verify_message\':safe(getattr(reason,\'verify_message\',str(reason))),\n                \'note\':\'Цепочка сертификата не подтверждена; причина на стороне сервера или доверенных CA пока не установлена.\'}\n    if isinstance(reason,socket.gaierror):\n        return {\'status\':\'dns_failed\',\'failed_phase\':\'dns\'}\n    if isinstance(reason,(TimeoutError,socket.timeout)):\n        return {\'status\':\'network_timeout\',\'failed_phase\':\'connect_or_read_unconfirmed\'}\n    return {\'status\':\'connection_unconfirmed\',\'failed_phase\':\'unconfirmed\'}\n\ndef tls_runtime_evidence():\n    """Local trust-store metadata only; never import or install a certificate."""\n    try:\n        paths=ssl.get_default_verify_paths();context=ssl.create_default_context()\n        return {\'openssl\':ssl.OPENSSL_VERSION,\'cafile\':paths.cafile,\'capath\':paths.capath,\n                \'trust_store\':context.cert_store_stats(),\n                \'verify_required\':context.verify_mode==ssl.CERT_REQUIRED,\n                \'hostname_check\':context.check_hostname}\n    except Exception as exc:return {\'error_type\':type(exc).__name__}\n\ndef read_public(url, hosts):\n    """Only GET fixed public origins, verified TLS; no credentials or cookies."""\n    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect(),\n             urllib.request.HTTPSHandler(context=ssl.create_default_context()))\n    began=time.monotonic(); requests=0; fragment_ignored=False\n    for hop in range(3):\n        if not approved_url(url,hosts): raise ValueError(\'url_not_approved\')\n        public_dns(urllib.parse.urlsplit(url).hostname)\n        requests+=1\n        req=urllib.request.Request(url,headers={\'User-Agent\':\'TenderAssistant/6.2 public source audit\',\'Accept\':\'text/html\',\'Accept-Encoding\':\'identity\'})\n        try: response=opener.open(req,timeout=7)\n        except urllib.error.HTTPError as exc:\n            if exc.code in (301,302,303,307,308):\n                target=urllib.parse.urljoin(url,exc.headers.get(\'Location\',\'\'))\n                # A fragment is client-side state, never sent in a GET. Retain\n                # the existing host/TLS/path/query checks on the actual target.\n                target,fragment=urllib.parse.urldefrag(target)\n                fragment_ignored=fragment_ignored or bool(fragment)\n                exc.close()\n                if hop==2: raise ValueError(\'redirect_limit\')\n                if target==url or not approved_url(target,hosts):\n                    raise SourceAccessError(\'redirect_not_approved\',http=exc.code,requests=requests,\n                        redirect_origin=redirect_origin(target),redirect_followed=False)\n                url=target; continue\n            return {\'http\':exc.code,\'body\':b\'\',\'url\':url,\'requests\':requests,\'complete\':True,\'content_type\':\'\'}\n        with response:\n            content_type=response.headers.get(\'Content-Type\',\'\')\n            if \'html\' not in content_type.lower():\n                return {\'http\':response.status,\'body\':b\'\',\'url\':url,\'requests\':requests,\'complete\':False,\'content_type\':content_type}\n            body=bytearray()\n            while len(body)<=MAX_BYTES:\n                if time.monotonic()-began>25: raise TimeoutError(\'source_time_budget\')\n                block=response.read(min(65536,MAX_BYTES+1-len(body)))\n                if not block: break\n                body.extend(block)\n            return {\'http\':response.status,\'body\':bytes(body),\'url\':url,\'requests\':requests,\n                    \'complete\':len(body)<=MAX_BYTES,\'content_type\':content_type,\n                    \'client_fragment_not_executed\':fragment_ignored}\n    raise ValueError(\'redirect_limit\')\n\ndef inspect_public(item, fetch=read_public):\n    row={\'source\':item[\'source\'],\'checked_at\':stamp(),\'pipeline_ready\':False,\'queued_count\':0}\n    if item.get(\'cost_policy\')==\'excluded_paid\':\n        return {**row,\'status\':\'skipped_paid_source\',\'requests\':0}\n    try:\n        response=fetch(item[\'url\'],item[\'hosts\'])\n        row.update({k:response.get(k) for k in (\'http\',\'url\',\'requests\',\'client_fragment_not_executed\')})\n        body=response.get(\'body\',b\'\')\n        row.update(bytes=len(body),sha256=hashlib.sha256(body).hexdigest())\n        if response.get(\'http\') in (401,403,429): row[\'status\']=\'access_limited\'; return row\n        if response.get(\'http\')!=200: row[\'status\']=\'http_error\'; return row\n        if not response.get(\'complete\'): row[\'status\']=\'response_incomplete\'; return row\n        if \'html\' not in response.get(\'content_type\',\'\').lower(): row[\'status\']=\'unexpected_content_type\'; return row\n        charset=re.search(r\'charset\\s*=\\s*[\\"\\\']?([\\w-]+)\',response[\'content_type\'],re.I)\n        encoding=charset.group(1) if charset else \'utf-8\'\n        try: text=body.decode(encoding)\n        except (LookupError,UnicodeError): row[\'status\']=\'encoding_unconfirmed\'; return row\n        page=PublicHTML(); page.feed(text)\n        visible=\' \'.join(\' \'.join(page.words).split())\n        if re.search(r\'captcha|access denied|доступ запрещ|подтвердите.{0,40}человек|проверка.{0,40}браузер|web application firewall\',visible[:8000],re.I):\n            row[\'status\']=\'access_challenge\'; return row\n        if page.gwt_panel and page.gwt_script:\n            row.update(status=\'public_search_requires_javascript\',text_characters=len(visible),\n                       public_search_shell_observed=True,hidden_login_form=page.hidden_password,\n                       coverage=\'public shell only; native search not called by this probe\')\n            return row\n        if page.password and len(visible)<2500: row[\'status\']=\'authentication_required\'; return row\n        evidence=[]; seen=set()\n        for href,title in page.links:\n            target=urllib.parse.urljoin(response[\'url\'],href).split(\'#\')[0]\n            if not approved_url(target,item[\'hosts\']) or target in seen: continue\n            if not re.search(r\'алюм|\\b(?:Д16|АД31|АМг\\d|АМц)\\b\',title,re.I): continue\n            if not re.search(r\'\\d\',urllib.parse.urlsplit(target).path): continue\n            if len(title.strip())<15: continue\n            seen.add(target)\n            evidence.append({\'title\':title[:500],\'url\':target,\'eligibility\':\'not_verified\'})\n            if len(evidence)>=10: break\n        row.update(status=\'public_link_evidence_only\' if evidence else\n                   (\'public_page_only\' if len(visible)>80 else \'public_listing_not_exposed\'),\n                   text_characters=len(visible),candidate_links=evidence,\n                   coverage=\'one_public_page; no keyword request, pagination, documents or quantity approval\')\n    except Exception as exc:\n        row.update(network_failure(exc),error_type=type(exc).__name__,reason=safe(exc))\n        if isinstance(exc,SourceAccessError):row.update(exc.evidence)\n        if row[\'status\']==\'tls_verification_failed\':row[\'tls_environment\']=tls_runtime_evidence()\n    return row\n\ndef check_new_sources(items):\n    # One independent page per source, never more than two simultaneous origins.\n    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:\n        return list(pool.map(inspect_public,items))\n\ndef render_review(data):\n    esc=lambda x:html.escape(str(x if x is not None else \'—\'),quote=True)\n    runtime=data.get(\'runtime\') or {}\n    rows=\'\'.join(\'<tr>\'+\'\'.join(\'<td>\'+esc(v)+\'</td>\' for v in\n        (r[\'name\'],r.get(\'capability\'),r.get(\'verdict_description\') or VERDICT_LABELS.get(r.get(\'verdict\'), \'Не проверено на сервере\'),\n         (r.get(\'report\') or {}).get(\'status\'),r.get(\'analysis_done_count\')))+\'</tr>\' for r in runtime.get(\'sources\',[]))\n    candidates=\'\'.join(\'<tr><td>\'+esc(r[\'name\'])+\'</td><td><a href="\'+esc(r[\'url\'])+\'">Официальный источник</a></td><td>\'+esc(r[\'potential\'])+\'</td><td>\'+esc(r[\'cost_note\'])+\'</td><td>\'+esc(r[\'next_step\'])+\'</td></tr>\' for r in data[\'potential_sources\'])\n    probes=\'\'.join(\'<li>\'+esc(r[\'source\'])+\': \'+esc(r[\'status\'])+\'</li>\' for r in data.get(\'public_checks\',[]))\n    return \'\'\'<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Источники закупок — проверка подключения</title><style>body{font:16px/1.5 system-ui;margin:32px auto;padding:0 20px;max-width:1200px;color:#173047}h1,h2{color:#103c60}table{border-collapse:collapse;width:100%;margin:20px 0}td,th{border:1px solid #ccd9e2;padding:10px;text-align:left;vertical-align:top}th{background:#eaf2f7}.note{background:#f2f6f8;padding:18px;border-left:4px solid #287aa6}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}a{color:#096995}</style><h1>Источники закупок</h1><p>Проверка: \'\'\'+esc(data[\'checked_at\'])+\'\'\'</p><div class="note">Доступность страницы, работа поиска и завершённый анализ — разные этапы. Этот отчёт не подключает площадки и не запускает OCR/LLM. Число анализов — за всё время, не число подходящих закупок. Бесплатный просмотр не означает бесплатное участие.</div><h2>Действующие подключения</h2><table><tr><th>Источник</th><th>Возможности кода</th><th>Наблюдение</th><th>Последний отчёт</th><th>Анализы завершены, всего</th></tr>\'\'\'+rows+\'\'\'</table><h2>Дополнительные источники</h2><table><tr><th>Источник</th><th>Ссылка</th><th>Потенциал и ограничения</th><th>Стоимость</th><th>Следующий шаг</th></tr>\'\'\'+candidates+\'\'\'</table><h2>Публичная проверка</h2><ul>\'\'\'+probes+\'\'\'</ul><h2>Критерии отбора</h2><p>Поставка целевого алюминиевого материала; актуальный срок; полные документы; одна позиция от 500 кг либо от 200 шт. при неизвестной массе. Низкая указанная масса не заменяется количеством штук. Объёмы разных позиций не суммируются. Лом, продажа имущества, химические соединения алюминия и случайные упоминания исключаются.</p><h2>Заказы на полимерную покраску</h2><p>Направление сохранено в плане. Ключи ниже предлагаются к настройке; поиск и прохождение фильтра услуг этим аудитом не включаются. Порог для услуг по площади отдельно не установлен.</p><pre>\'\'\'+esc(\'\\n\'.join(COATING_PROPOSED))+\'\'\'</pre><h2>Доказательства и ограничения</h2><pre>\'\'\'+esc(json.dumps(data,ensure_ascii=False,indent=2,default=str))+\'\'\'</pre></html>\'\'\'\n\ndef make_review(catalog, potentials, runtime=None, probes=None):\n    return {\'version\':AUDIT_VERSION,\'checked_at\':stamp(),\n        \'scope\':\'current runtime snapshot plus shortlisted public-source probes; not all Tenderplan sites\',\n        \'reference_catalog\':\'https://tenderplan.ru/landing/platforms\',\n        \'runtime\':runtime or {\'sources\':[{**r,\'verdict\':\'not_checked_on_server\'} for r in catalog]},\n        \'potential_sources\':potentials,\'public_checks\':probes or [],\n        \'business_tasks_submitted\':0,\'new_sources_enabled\':0,\n        \'no_documents_ocr_llm\':True,\'no_business_db_writes\':True}\n'
