SOURCE_AUDIT_TESTS = 'import unittest\nfrom unittest.mock import patch\nfrom tempfile import TemporaryDirectory\n\nclass SourceAuditTests(unittest.TestCase):\n    def item(self): return next(r for r in SOURCE_POTENTIALS if r[\'source\']==\'alrosa\')\n    def response(self,text=\'<html><body>Открытый реестр закупок товаров и услуг предприятия</body></html>\',**kwargs):\n        return {\'body\':text.encode(),\'http\':200,\'url\':self.item()[\'url\'],\'requests\':1,\n                \'complete\':True,\'content_type\':\'text/html; charset=utf-8\',**kwargs}\n    def probe(self,text=None,**kwargs):\n        response=self.response(**kwargs) if text is None else self.response(text,**kwargs)\n        return inspect_public(self.item(),lambda *args:response)\n    def test_catalog_identity_and_owner_pauses(self):\n        ids=[x[\'source\'] for x in SOURCE_CATALOG]\n        self.assertEqual(len(ids),len(set(ids)))\n        self.assertEqual(len(SOURCE_CATALOG),44)\n        self.assertTrue({\'alfalot\',\'vladzakupki\'}.issubset(ids))\n        for source in (\'ast_goz\',\'etprf\'):\n            self.assertTrue(next(x for x in SOURCE_CATALOG if x[\'source\']==source)[\'disabled_by_owner\'])\n        self.assertFalse(next(x for x in SOURCE_CATALOG if x[\'source\']==\'tender_pro\')[\'disabled_by_owner\'])\n        self.assertIn(\'zakazrf\',[x[\'source\'] for x in SOURCE_POTENTIALS])\n        self.assertNotIn(\'zakazrf\',ids)\n    def test_fixed_https_catalog(self):\n        for item in SOURCE_POTENTIALS:\n            self.assertTrue(approved_url(item[\'url\'],item[\'hosts\']))\n            self.assertEqual(item[\'adapter_installed_by_this_file\'], item[\'source\'] in {row[\'source\'] for row in SOURCE_CATALOG})\n    def test_paid_sources_not_requested(self):\n        for item in SOURCE_POTENTIALS:\n            if item[\'cost_policy\']==\'excluded_paid\':\n                result=inspect_public(item,lambda *a:self.fail(\'paid source requested\'))\n                self.assertEqual(result[\'requests\'],0)\n                self.assertEqual(result[\'status\'],\'skipped_paid_source\')\n    def test_http200_is_not_pipeline_success(self):\n        result=self.probe()\n        self.assertFalse(result[\'pipeline_ready\']);self.assertEqual(result[\'queued_count\'],0)\n        self.assertNotIn(result[\'status\'],(\'connected\',\'ready\',\'ok\'))\n    def test_partial_body_not_empty_search(self):\n        self.assertEqual(self.probe(complete=False)[\'status\'],\'response_incomplete\')\n    def test_failures_not_empty_search(self):\n        for status in (401,403,429): self.assertEqual(self.probe(http=status)[\'status\'],\'access_limited\')\n        for status in (404,500,502,503): self.assertEqual(self.probe(http=status)[\'status\'],\'http_error\')\n        def fail(*args): raise TimeoutError(\'timeout\')\n        self.assertEqual(inspect_public(self.item(),fail)[\'status\'],\'network_timeout\')\n    def test_captcha_and_auth_stop(self):\n        self.assertEqual(self.probe(\'<html>Подтвердите, что вы человек CAPTCHA</html>\')[\'status\'],\'access_challenge\')\n        self.assertEqual(self.probe(\'<form><input type="password">Войти</form>\')[\'status\'],\'authentication_required\')\n    def test_hidden_login_does_not_claim_authentication_required(self):\n        page=\'<form class="spf-hidden"><input type="password">Войти</form><h1>Поиск торгово-закупочных процедур</h1><div id="gwtSearchPanel"></div><script src="/etp/guigwt.default/guigwt.default.nocache.js"></script>\'\n        result=self.probe(page)\n        self.assertEqual(result[\'status\'],\'public_search_requires_javascript\')\n        self.assertTrue(result[\'hidden_login_form\']);self.assertFalse(result[\'pipeline_ready\'])\n        self.assertEqual(self.probe(\'<form hidden><input type="password"></form>\')[\'status\'],\'public_listing_not_exposed\')\n    def test_safe_fragment_redirect_is_read_without_client_state(self):\n        url=self.item()[\'url\'];target=url.rstrip(\'/\')+\'/app/SearchLots/page\'\n        class Response:\n            status=200;headers={\'Content-Type\':\'text/html\'}\n            def __enter__(self):return self\n            def __exit__(self,*args):pass\n            def read(self,*args):return b\'\'\n        calls=[]\n        class Opener:\n            def open(self,request,**kw):\n                calls.append(request.full_url)\n                if len(calls)==1:raise urllib.error.HTTPError(url,301,\'Moved\',{\'Location\':target+\'#public-search-state\'},None)\n                return Response()\n        with patch.object(urllib.request,\'build_opener\',return_value=Opener()),patch.object(socket,\'getaddrinfo\',return_value=[(None,None,None,None,(\'8.8.8.8\',443))]):\n            result=read_public(url,self.item()[\'hosts\'])\n        self.assertEqual(calls,[url,target]);self.assertTrue(result[\'client_fragment_not_executed\'])\n        self.assertFalse(approved_url(target+\'?token=secret\',self.item()[\'hosts\']))\n    def test_script_is_not_visible_evidence(self):\n        self.assertEqual(self.probe(\'<script>captcha алюминий</script>\')[\'status\'],\'public_listing_not_exposed\')\n    def test_navigation_not_candidate(self):\n        result=self.probe(\'<a href="/catalog/aluminium">Алюминиевые листы и профили</a>\')\n        self.assertFalse(result[\'candidate_links\'])\n    def test_public_link_evidence_not_qualified_purchase(self):\n        result=self.probe(\'<a href="/tender/123">Поставка алюминиевого листа</a>\')\n        self.assertEqual(result[\'status\'],\'public_link_evidence_only\')\n        self.assertEqual(result[\'candidate_links\'][0][\'eligibility\'],\'not_verified\')\n        self.assertFalse(result[\'pipeline_ready\'])\n    def test_reject_foreign_hosts_and_secrets(self):\n        for url in (\'http://zakupki.alrosa.ru/\',\'https://zakupki.alrosa.ru.evil.test/\',\n                    \'https://u:p@zakupki.alrosa.ru/\',\'https://zakupki.alrosa.ru:8443/\',\n                    \'https://127.0.0.1/\',\'https://zakupki.alrosa.ru/?token=x\',\n                    \'https://zakupki.alrosa.ru/login\',\'file:///etc/passwd\'):\n            self.assertFalse(approved_url(url,self.item()[\'hosts\']),url)\n    def test_private_dns_rejected(self):\n        for address in (\'127.0.0.1\',\'10.0.0.1\',\'169.254.169.254\',\'::1\'):\n            with patch.object(socket,\'getaddrinfo\',return_value=[(None,None,None,None,(address,443))]):\n                with self.assertRaisesRegex(ValueError,\'non_public_address\'):public_dns(\'example.test\')\n    def test_time_requires_timezone_and_no_future_success(self):\n        now=datetime(2026,11,13,tzinfo=timezone.utc)\n        self.assertIsNone(age_hours(\'2026-11-14T00:00:00+00:00\',now))\n        self.assertIsNone(age_hours(\'2026-11-12\',now))\n        self.assertEqual(age_hours(\'2026-11-12T20:00:00+00:00\',now),4)\n    def test_verdict_queued_is_not_analysis_completion(self):\n        row={\'source\':\'gpb\',\'capability\':\'pipeline\',\'schedule\':[1],\n             \'report\':{\'checked_at\':\'date\',\'age_hours\':1,\'status\':\'ok\',\'pipeline_outcomes\':{\'queued\':2}},\n             \'analysis_done_count\':None}\n        self.assertEqual(connection_verdict(row),\'recent_collection_analysis_unconfirmed\')\n        row[\'analysis_done_count\']=2\n        self.assertEqual(connection_verdict(row),\'recent_collection_and_past_analyses\')\n        row[\'report\'][\'age_hours\']=7\n        self.assertEqual(connection_verdict(row),\'stale_report\')\n    def test_partial_and_disabled_not_green(self):\n        self.assertEqual(connection_verdict({\'disabled_by_owner\':True}),\'disabled_by_owner\')\n        row={\'report\':{\'checked_at\':\'date\',\'age_hours\':1,\'status\':\'partial\'},\'schedule\':[1]}\n        self.assertEqual(connection_verdict(row),\'partial_coverage\')\n    def test_actual_server_unavailable_statuses_not_working_monitors(self):\n        for status,expected in (\n            (\'public_listing_not_exposed\',\'public_listing_unavailable\'),\n            (\'requires_adapter\',\'adapter_required\'),(\'unavailable\',\'attention_required\'),\n            (\'public_data_requires_review\',\'public_data_needs_review\')):\n            row={\'report\':{\'status\':status,\'checked_at\':\'date\',\'age_hours\':1},\n                 \'schedule\':[1],\'capability\':\'candidates_only\'}\n            self.assertEqual(connection_verdict(row),expected)\n    def test_certificate_failure_keeps_verified_tls(self):\n        failure=ssl.SSLCertVerificationError(1,\'unable to get local issuer certificate\')\n        failure.verify_code=20;failure.verify_message=\'unable to get local issuer certificate\'\n        def fetch(*args):raise urllib.error.URLError(failure)\n        result=inspect_public(self.item(),fetch)\n        self.assertEqual(result[\'status\'],\'tls_verification_failed\')\n        self.assertEqual(result[\'verify_code\'],20)\n        self.assertFalse(result[\'pipeline_ready\'])\n        self.assertTrue(result[\'tls_environment\'][\'verify_required\'])\n        self.assertTrue(result[\'tls_environment\'][\'hostname_check\'])\n    def test_dns_failure_separate_from_tls(self):\n        for failure in (socket.gaierror(-2,\'Name not known\'),urllib.error.URLError(socket.gaierror(-2,\'Name not known\'))):\n            self.assertEqual(network_failure(failure)[\'status\'],\'dns_failed\')\n    def test_redirect_evidence_no_credentials_or_implicit_trust(self):\n        url=self.item()[\'url\']\n        failure=urllib.error.HTTPError(url,302,\'Found\',{\'Location\':\'https://user:password@other.example/path/secret?token=value\'},None)\n        class Opener:\n            def open(self,*args,**kwargs):raise failure\n        with patch.object(urllib.request,\'build_opener\',return_value=Opener()),patch.object(socket,\'getaddrinfo\',return_value=[(None,None,None,None,(\'8.8.8.8\',443))]):\n            result=inspect_public(self.item())\n        self.assertEqual(result[\'redirect_origin\'],\'https://other.example\')\n        self.assertEqual(result[\'requests\'],1)\n        self.assertFalse(result[\'redirect_followed\'])\n        serialized=json.dumps(result)\n        self.assertNotIn(\'password\',serialized);self.assertNotIn(\'token=value\',serialized)\n    def test_invalid_report_cannot_be_hidden_by_successful_last_run(self):\n        row={\'report\':{\'status\':\'unreadable_report\'},\'last_run\':{\'status\':\'ok\',\'age_hours\':1},\'schedule\':[1]}\n        self.assertEqual(connection_verdict(row),\'attention_required\')\n    def test_separate_collector_can_be_observed_without_primary_report(self):\n        row={\'source\':\'zakupki_gov_ru\',\'capability\':\'pipeline\',\'schedule\':[1],\n             \'report\':{\'status\':\'primary_report_missing\'},\'last_run\':{\'status\':\'queued\',\'age_hours\':8}}\n        self.assertEqual(connection_verdict(row),\'recent_collection_analysis_unconfirmed\')\n    def test_invalid_report_is_explicit(self):\n        now=datetime.now(timezone.utc)\n        for data in ([],{\'pipeline\':{}},{\'errors\':\'bad\'}):\n            if data=={\'pipeline\':{}}:continue\n            self.assertEqual(summarize_report(data,now)[\'status\'],\'invalid_report\')\n    def test_keywords_never_enable_services(self):\n        with TemporaryDirectory() as d:\n            root=Path(d);p=root/\'app/scoring/selection_policy.py\';p.parent.mkdir(parents=True)\n            p.write_text("FALLBACK_QUERIES=(\'алюминий\',\'полимерная покраска алюминия\')")\n            result=literal_keywords(root)\n        self.assertEqual(result[\'coating_end_to_end_enabled\'],\'not_verified\')\n        self.assertEqual(len(result[\'literal_query_lists\'][0][\'values\']),2)\n    def test_html_escapes_untrusted_report(self):\n        report=make_review(SOURCE_CATALOG,SOURCE_POTENTIALS)\n        report[\'public_checks\']=[{\'source\':\'<script>alert(1)</script>\',\'status\':\'<img onerror=x>\'}]\n        rendered=render_review(report)\n        self.assertNotIn(\'<script>\',rendered);self.assertNotIn(\'<img\',rendered)\n        self.assertIn(\'&lt;script&gt;\',rendered)\n    def test_no_business_action_calls(self):\n        # The audited core must remain observation-only; imports do not call adapters.\n        tree=ast.parse(SOURCE_AUDIT_CODE_FOR_TEST)\n        forbidden={\'delay\',\'apply_async\',\'send_task\',\'purge\',\'revoke\',\'commit\',\'ack\',\'basic_ack\',\'lpop\',\'rpop\',\'delete\',\'unlink\'}\n        calls={n.func.attr for n in ast.walk(tree) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute)}\n        self.assertFalse(calls & forbidden,calls & forbidden)\n\nsuite=unittest.defaultTestLoader.loadTestsFromTestCase(SourceAuditTests)\nresult=unittest.TextTestRunner(verbosity=2).run(suite)\nif not result.wasSuccessful():raise SystemExit(1)\nprint(\'SOURCE_AUDIT_TESTS_OK:\',result.testsRun,\'offline checks; no Docker/network/DB/queues/LLM\')\n'
def source_audit_namespace():
    scope={'__name__':'embedded_source_audit'}
    exec(compile(SOURCE_AUDIT_CODE,'source_audit','exec'),scope)
    return scope

def source_audit_self_test():
    scope=source_audit_namespace()
    scope.update(SOURCE_CATALOG=SOURCE_CATALOG,SOURCE_POTENTIALS=SOURCE_POTENTIALS,SOURCE_AUDIT_CODE_FOR_TEST=SOURCE_AUDIT_CODE)
    exec(compile(SOURCE_AUDIT_TESTS,'source_audit_tests','exec'),scope)

def source_audit_json_process(command, script, timeout=120):
    result=subprocess.run(command,input=script,text=True,capture_output=True,timeout=timeout,check=False)
    lines=[line[len('SOURCE_AUDIT_JSON:'):] for line in result.stdout.splitlines() if line.startswith('SOURCE_AUDIT_JSON:')]
    if result.returncode!=0 or len(lines)!=1:
        raise ValueError('audit_process_incomplete_exit_'+str(result.returncode))
    return json.loads(lines[0])

def source_audit_run(root, catalog_only=False):
    import tempfile
    scope=source_audit_namespace()
    runtime=None;probes=[];errors=[];services=[];service=None
    if not catalog_only:
        print('SOURCE_CONNECTION_AUDIT: configuration/reports/DB snapshot; public probes; no business tasks',flush=True)
        try:
            result=subprocess.run(['docker','compose','ps','--services','--status','running'],
                                  text=True,capture_output=True,timeout=20,check=True)
            services=sorted(set(result.stdout.split()))
            service=next((s for s in ('app','celery_discovery','celery_worker') if s in services),None)
        except (OSError,subprocess.SubprocessError):
            errors.append({'phase':'compose','reason':'runtime_unavailable; no services started'})
        if service:
            script='import signal\nsignal.alarm(75)\n'+SOURCE_AUDIT_CODE+'\nprint("SOURCE_AUDIT_JSON:"+json.dumps(runtime_inventory('+repr(SOURCE_CATALOG)+'),ensure_ascii=False,default=str))\n'
            try:
                runtime=source_audit_json_process(['docker','compose','exec','-T',service,'python','-'],script)
            except (OSError,subprocess.SubprocessError,ValueError):
                errors.append({'phase':'runtime','reason':'runtime_audit_incomplete'})
        else:
            errors.append({'phase':'runtime','reason':'no_running_app_or_worker; runtime not checked'})
        # Public checks run in the same image/network as the app when it is available.
        # Each source is isolated: a timeout cannot be interpreted as an empty listing.
        command=['docker','compose','exec','-T',service,'python','-'] if service else [sys.executable,'-']
        for item in SOURCE_POTENTIALS:
            print('CHECKING_SOURCE:',item['source'],flush=True)
            script='import signal\nsignal.alarm(35)\n'+SOURCE_AUDIT_CODE+'\nprint("SOURCE_AUDIT_JSON:"+json.dumps(inspect_public('+repr(item)+'),ensure_ascii=False))\n'
            try:
                probe=source_audit_json_process(command,script,timeout=45)
            except (OSError,subprocess.SubprocessError,ValueError):
                probe={'source':item['source'],'status':'probe_incomplete','pipeline_ready':False,'queued_count':0}
            probe['network_origin']='container:'+service if service else 'host; container connectivity unverified'
            probes.append(probe)
            print(json.dumps({k:probe.get(k) for k in ('source','status','http','requests','error_type','reason','failed_phase','verify_code','verify_message','tls_environment','redirect_origin','redirect_followed','network_origin','candidate_links')},ensure_ascii=False),flush=True)
    report=scope['make_review'](SOURCE_CATALOG,SOURCE_POTENTIALS,runtime,probes)
    report.update(mode='catalog_only_no_http' if catalog_only else 'runtime_and_public_access',
                  running_services=services,audit_errors=errors,
                  current_server_state_verified=bool(runtime and not runtime.get('errors')),
                  queues_checked=False,
                  queue_note='Для снимка брокера используйте --audit-queues; текущий аудит не подтверждает пустоту очередей.')
    folder=Path(tempfile.mkdtemp(prefix='tender-source-review-',dir=str(root)))
    report_path=folder/'report.json';html_path=folder/'report.html'
    report_path.write_text(json.dumps(report,ensure_ascii=False,indent=2,default=str),encoding='utf-8')
    html_path.write_text(scope['render_review'](report),encoding='utf-8')
    print('\nEXISTING_SOURCES:',flush=True)
    for row in report['runtime'].get('sources',[]):
        print(json.dumps({k:row.get(k) for k in ('source','name','capability','verdict','verdict_description','schedule','report','last_run','analysis_done_count')},ensure_ascii=False,default=str),flush=True)
    print('SEARCH_FILTERS:',json.dumps(report['runtime'].get('keywords',{'status':'runtime_not_checked'}),ensure_ascii=False),flush=True)
    print('\nPOTENTIAL_SOURCES:',flush=True)
    for row in SOURCE_POTENTIALS:
        print(json.dumps({k:row[k] for k in ('source','name','url','cost_policy','cost_note','next_step')},ensure_ascii=False),flush=True)
    print('REPORT_JSON:',report_path,flush=True)
    print('REPORT_HTML:',html_path,flush=True)
    print('SOURCE_AUDIT_FINISHED: diagnostic files only; no installs/restarts, schedules, DB writes, document downloads, tasks, OCR or LLM',flush=True)
    if errors or (runtime and runtime.get('errors')):
        print('SERVER_AUDIT_INCOMPLETE:',json.dumps(errors+(runtime or {}).get('errors',[]),ensure_ascii=False),flush=True)


def public_progress_check(root):
    """Print prospective source availability from the app network, no artifacts."""
    chosen=('onlinecontract','setonline','gazneftetorg','eltox','avtodor','zakupki21','region','spbex')
    result=subprocess.run(['docker','compose','ps','--services','--status','running'],text=True,capture_output=True,timeout=20,check=True)
    running=set(result.stdout.split());service=next((s for s in ('app','celery_discovery','celery_worker') if s in running),None)
    if service is None:raise SystemExit('PUBLIC_CHECK_NO_RUNNING_APP: no services started')
    for key in chosen:
        item=next(r for r in SOURCE_POTENTIALS if r['source']==key)
        script='import signal\nsignal.alarm(35)\n'+SOURCE_AUDIT_CODE+'\nprint("SOURCE_AUDIT_JSON:"+json.dumps(inspect_public('+repr(item)+'),ensure_ascii=False))\n'
        print('CHECKING_TENDERPLAN_PUBLIC:',item['name'],flush=True)
        try:row=source_audit_json_process(['docker','compose','exec','-T',service,'python','-'],script,timeout=45)
        except (OSError,subprocess.SubprocessError,ValueError):row={'source':key,'status':'probe_incomplete','pipeline_ready':False,'queued_count':0}
        row['network_origin']='container:'+service
        print(json.dumps(row,ensure_ascii=False,default=str),flush=True)
    print('READ_ONLY_TENDERPLAN: public entry pages only; no files, documents, DB edits, tasks, OCR/LLM or source activation',flush=True)

