def v24_reverse(root):
    for rel,old,new,count in reversed(V24_EDITS):
        p=root/rel
        if p.is_file():
            s=p.read_text()
            if s.count(new)==count:p.write_text(s.replace(new,old))

def v24_apply(root):
    for rel,old,new,count in V24_EDITS:
        p=root/rel;s=p.read_text()
        if s.count(old)!=count or new in s:
            raise SystemExit('V24_PUBLIC_CONTRACT_CHANGED: '+rel+'; no project changes')
        p.write_text(s.replace(old,new))

def v24_runtime_check(root,catalog_only=False,documents=False):
    if catalog_only:
        import types,sys,tempfile
        namespace={}
        # Offline export works without Docker and without third-party imports.
        exec(UNIFIED_MODULES['app/sources/tenderplan_catalog.py'],namespace)
        import html
        folder=Path(tempfile.mkdtemp(prefix='tenderplan-catalog-',dir=str(root)))
        data={'version':namespace['VERSION'],'reference_urls':namespace['EVIDENCE'],'entries':namespace['ENTRIES'],
              'configured_sources':SOURCE_CATALOG,'access_policy':'free_public_only','runtime_checked':False}
        path=folder/'catalog.json';path.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')
        print('CATALOG_JSON:',path);return
    if documents:
        code=V24_DOCUMENTS_CHECK
