def unified_verification_version_checks(program=None, modules=None):
    """Validate version assertions against the payload without importing app code.

    This complements (does not replace) container/runtime verification. Imported
    version aliases are resolved in statement order, including reused VERSION.
    """
    import ast
    program = unified_verification_script() if program is None else program
    modules = UNIFIED_MODULES if modules is None else modules
    literals = {}
    for path, source in modules.items():
        if not path.endswith('.py'):
            continue
        values = {}
        for node in ast.parse(source).body:
            if isinstance(node, ast.Assign):
                targets, value = node.targets, node.value
            elif isinstance(node, ast.AnnAssign):
                targets, value = [node.target], node.value
            else:
                continue
            for target in targets:
                if isinstance(target, ast.Name) and 'VERSION' in target.id and isinstance(value, ast.Constant) and isinstance(value.value, str):
                    values[target.id] = value.value
        literals[path[:-3].replace('/', '.')] = values
    bindings = {}; checked = []
    def resolve(node):
        if isinstance(node, ast.Name):
            binding = bindings.get(node.id)
            return binding if binding and binding[1] is not None else None
        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name):
            binding = bindings.get(node.value.id)
            if binding and binding[1] is None and node.attr in literals.get(binding[0], {}):
                return binding[0], node.attr
        return None
    for statement in ast.parse(program).body:
        if isinstance(statement, ast.ImportFrom):
            module = statement.module or ''
            for item in statement.names:
                alias = item.asname or item.name
                bindings.pop(alias, None)
                if item.name in literals.get(module, {}):
                    bindings[alias] = (module, item.name)
                elif module + '.' + item.name in literals:
                    bindings[alias] = (module + '.' + item.name, None)
        elif isinstance(statement, ast.Import):
            for item in statement.names:
                if item.asname:
                    bindings.pop(item.asname, None)
                    if item.name in literals:bindings[item.asname] = (item.name, None)
        elif isinstance(statement, (ast.Assign, ast.AnnAssign)):
            targets = statement.targets if isinstance(statement, ast.Assign) else [statement.target]
            for target in targets:
                for child in ast.walk(target):
                    if isinstance(child, ast.Name):bindings.pop(child.id, None)
        if not isinstance(statement, ast.Assert):
            continue
        for node in ast.walk(statement.test):
            if not isinstance(node, ast.Compare) or len(node.ops)!=1 or not isinstance(node.ops[0], ast.Eq):
                continue
            left, right = node.left, node.comparators[0]
            ref = resolve(left)
            if ref is None:
                ref = resolve(right); left, right = right, left
            if ref is None or not isinstance(right, ast.Constant) or not isinstance(right.value, str):
                continue
            module, name = ref; actual = literals[module][name]
            expected = right.value
            if actual != expected:
                raise SystemExit('UNIFIED_VERIFICATION_VERSION_MISMATCH: ' + module + '.' + name +
                                 '; payload=' + actual + '; verification=' + expected +
                                 '; installation not started')
            checked.append({'module':module, 'constant':name, 'version':actual})
    return checked



